INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1018','contact','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->contact[\'contact\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n	<form action=\"contact.php\" method=\"post\">\r\n	<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	<input type=\"hidden\" name=\"from\" value=\"{$redirect_url}\" />\r\n	<div class=\"container-md\">\r\n		\r\n		\r\n		{$errors}\r\n		<div class=\"card\">\r\n<div class=\"card-body\">\r\n		\r\n		<div class=\"form-group fw-bold pb-4 mb-3 border-bottom\">\r\n			<label class=\"fs-6\">{$lang->contact[\'contact_subject\']}</label><br />\r\n			<span class=\"text-desc small fw-normal\">{$lang->contact[\'contact_subject_desc\']}</span>\r\n			<input type=\"text\" name=\"subject\" class=\"form-control form-control-sm border\" value=\"{$contact_subject}\" />\r\n		</div>\r\n		\r\n		<div class=\"form-group fw-bold pb-4 mb-3 border-bottom\">\r\n			<label class=\"fs-6\">{$lang->contact[\'contact_message\']}</label><br />\r\n			<span class=\"text-desc small fw-normal\">{$lang->contact[\'contact_message_desc\']}</span>\r\n			<textarea style=\"height: 200px; resize: none\" class=\"form-control form-control-sm border\" name=\"message\" class=\"textarea\" >{$contact_message}</textarea>\r\n		</div>\r\n	\r\n			<div class=\"form-group fw-bold pb-4\">\r\n			<label class=\"fs-6\">{$lang->contact[\'contact_email\']}</label>\r\n				<br /><span class=\"text-desc small fw-normal\">{$lang->contact[\'contact_email_desc\']}</span>\r\n			<input type=\"text\" name=\"email\" class=\"form-control form-control-sm border\" value=\"{$user_email}\" />\r\n		</div>\r\n		{$captcha}\r\n	</div>\r\n	\r\n	<div class=\"card-footer text-center\">\r\n		<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->contact[\'contact_send\']}\"><i class=\"fa-solid fa-envelope\"></i> &nbsp;{$lang->contact[\'contact_send\']}</button>\r\n	</div>\r\n	</div>\r\n			</div>\r\n\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1019','debug_summary','<div class=\"container-md\"><div id=\"debug\" class=\"card shadow-sm p-3 mt-4\">\r\n	<div class=\"row\">\r\n		<div class=\"col align-self-center\">{$generated_in} {$debug_weight} - {$sql_queries} / {$server_load} / {$memory_usage}</div>\r\n		<div class=\"col-auto align-self-center text-end\"><a href=\"{$debuglink}\" target=\"_blank\" class=\"btn btn-sm btn-secondary\">{$lang->debug_advanced_details}</a></div>\r\n	</div></div></div>','2','1837','','1720609281');
