INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1038','forumbit_depth1_forum_lastpost','<avatarep_uid_[{$lastpost_data[\'lastposteruid\']}]><div class=\"d-none d-md-block d-lg-block gridh\">\r\n	<p style=\"margin-bottom: 0px\"><a href=\"{$lastpost_link}\"><span class=\"fw-bold\">{$lastpost_subject}</span></a><br /><svg class=\"bi bi-reply-all-fill text-muted\" xmlns=\"http://www.w3.org/2000/svg\" width=\"1em\" height=\"1em\" fill=\"currentColor\" viewBox=\"0 0 16 16\">\r\n            <path d=\"M8.021 11.9 3.453 8.62a.719.719 0 0 1 0-1.238L8.021 4.1a.716.716 0 0 1 1.079.619V6c1.5 0 6 0 7 8-2.5-4.5-7-4-7-4v1.281c0 .56-.606.898-1.079.62z\"></path>\r\n            <path d=\"M5.232 4.293a.5.5 0 0 1-.106.7L1.114 7.945a.5.5 0 0 1-.042.028.147.147 0 0 0 0 .252.503.503 0 0 1 .042.028l4.012 2.954a.5.5 0 1 1-.593.805L.539 9.073a1.147 1.147 0 0 1 0-1.946l3.994-2.94a.5.5 0 0 1 .699.106z\"></path>\r\n		</svg> {$lastpost_profilelink} <span class=\"text-muted\">{$lastpost_date}</span></p>\r\n	\r\n	<div class=\"text-end\">\r\n	<a href=\"{$forum_url}\"><p class=\"text-end badge badge-warning catmod p-2 mb-0\">\r\n		 {$forum[\'name\']} &nbsp; \r\n		</p></a>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1039','forumbit_depth2_cat','<div class=\"row p-0\">\r\n		<div class=\"col-1 align-self-center d-none d-md-block d-lg-block\" style=\"width:50px\">\r\n        <div id=\"mark_read_{$forum[\'fid\']}\" class=\"forum_status forum_{$lightbulb[\'folder\']} ajax_mark_read\" title=\"{$lightbulb[\'altonoff\']}\"><i class=\"bi bi-chat-fill\"></i></div>\r\n    </div>\r\n    <div class=\"col-3 align-self-center p-2\" style=\"width:500px\">\r\n         <div><strong><a href=\"{$forum_url}\">{$forum[\'name\']}</a></strong>{$forum_viewers_text}<div class=\"smalltext\" style=\"font-size: 16px;\">{$forum[\'description\']}{$modlist}{$subforums}</div>\r\n        </div>\r\n    </div>\r\n    <div class=\"col align-self-center text-center d-none d-lg-block\"  style=\"width:auto\">\r\n        <div>{$threads}{$unapproved[\'unapproved_threads\']}<br />\r\n            <p class=\"text-muted\" style=\"font-size: 13px;margin-top: 0px;\">threads</p>\r\n        </div>\r\n    </div>\r\n    <div class=\"col align-self-center text-center d-none d-lg-block\"  style=\"width:auto\">\r\n        <div>{$posts}{$unapproved[\'unapproved_posts\']}<p class=\"text-muted\" style=\"font-size: 13px;margin-top: 0px;\">posts hi</p>\r\n        </div>\r\n    </div>\r\n    <div class=\"col-1 align-self-center d-none d-lg-block\"  style=\"width:auto\">\r\n        <div class=\"bg-light justify-content-center align-items-center align-content-center align-self-center border rounded border-1\" style=\"padding: 6px;width: 50px;height: 50px;float: right;margin-right: 20px;\"><svg class=\"bi bi-person-fill text-black-50\" width=\"1em\" height=\"1em\" viewBox=\"0 0 16 16\" style=\"font-family: Quicksand, sans-serif;font-size: 30px;\">\r\n                <path d=\"M3 14s-1 0-1-1 1-4 6-4 6 3 6 4-1 1-1 1H3zm5-6a3 3 0 1 0 0-6 3 3 0 0 0 0 6z\"></path>\r\n            </svg></div>\r\n    </div>\r\n    <div class=\"col-2 align-self-center text