INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1066','forumdisplay_thread','<div class=\"card border-bottom border-0 rounded-0\">\r\n	<div class=\"card-body py-0 px-1 inline_row {$bgcolor}\">\r\n<div class=\"row py-2\">\r\n		<div class=\"col align-self-center ms-2\">\r\n			\r\n			\r\n	<h6 class=\"mb-0 text-forum\"><a href=\"{$thread[\'threadlink\']}\">{$thread[\'threadprefix\']}<span class=\"{$inline_edit_class} {$new_class}\" id=\"tid_{$inline_edit_tid}\">{$thread[\'subject\']}</span></h6>\r\n		<div class=\"links small\">{$lang->forumdisplay[\'by\']} {$thread[\'profilelink\']}</div>\r\n		\r\n		<div class=\"d-block d-sm-block d-md-block d-lg-none d-xl-none d-xxl-none mt-1\">\r\n			<span class=\"{$thread_type_class}\"></span>{$icon}{$attachment_count}<span class=\"thread_status {$folder}\" title=\"{$folder_label}\"></span>\r\n		</div>\r\n		\r\n		</div>\r\n			<div class=\"col-auto d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block align-self-center text-end\">\r\n			<span class=\"{$thread_type_class}\"></span>{$icon} {$attachment_count}<span class=\"thread_status {$folder}\" title=\"{$folder_label}\"></span>\r\n				{$thread[\'multipage\']}\r\n			</div>\r\n		<div class=\"col-1 d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block align-self-center text-center\">\r\n			\r\n			<h6 class=\"mb-0\"><a href=\"{$BASEURL}/misc.php?action=whoposted&tid={$thread[\'tid\']}\" onclick=\"MyBB.whoPosted({$thread[\'tid\']}); return false;\">{$thread[\'replies\']}</a></h6><span class=\"text-muted small\">{$lang->forumdisplay[\'replies\']}</span>\r\n			\r\n		</div>\r\n			\r\n		<div class=\"col-12 col-sm-12 col-md-12 col-lg-3 col-xl-3 col-xxl-3 mt-3 mt-sm-3 mt-md-3 mt-lg-0\">\r\n			<div class=\"row\">\r\n				<div class=\"col-auto align-self-center\">\r\n					<avatarep_uid_[{$thread[\'lastposteruid\']}]>\r\n				</div>\r\n				<div class=\"col align-self-center me-2\">{$lastposterlink}<br /><span class=\"small text-muted text-uppercase\">{$lastpostdate}</span> {$modbit}\r\n					</div>\r\n				</div>\r\n				\r\n				\r\n				\r\n				\r\n			</div>\r\n			</div>\r\n	</div>\r\n			</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1067','forumdisplay_threadlist','<div class=\"row m-0 me-0 pe-0 p-0 mb-3\">\r\n		<div class=\"col ms-0 ps-0 text-center text-sm-center text-md-center text-lg-start align-self-center\">\r\n			{$multipage}\r\n		</div>\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg-auto col-xl-auto col-xxl-auto mt-3 mt-sm-3 mt-md-3 mt-lg-0 me-0 pe-0 text-end align-self-center\">\r\n		<a href=\"misc.php?action=markread&amp;fid={$fid}{$post_code_string}\" class=\"btn btn-secondary\" title=\"{$lang->forumdisplay[\'markforum_read\']}\">&nbsp;<i class=\"fa-solid fa-check\"></i>&nbsp;</a> &nbsp; {$addremovesubscription} &nbsp; {$newthread}\r\n	</div>\r\n</div>\r\n\r\n<div class=\"card border-0\">\r\n<div class=\"card-header py-3 bg-nav rounded border-bottom-0\">\r\n	\r\n	<div class=\"row\">\r\n		<div class=\"col\">\r\n	<p class=\"mb-0\"><a href=\"{$sorturl}&amp;sortby=subject&amp;order=asc\">{$lang->forumdisplay[\'thread\']}</a> {$orderarrow[\'subject\']} &mdash; <a href=\"{$sorturl}&amp;sortby=starter&amp;order=asc\">{$lang->forumdisplay[\'author\']}</a></p>\r\n		</div>\r\n		<div class=\"col-1 d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block text-center\">\r\n			<p class=\"mb-0\">\r\n				&nbsp;<a href=\"{$sorturl}&amp;sortby=replies&amp;order=desc\">{$lang->forumdisplay[\'replies\']}</a>\r\n			</p>\r\n		</div>\r\n		<div class=\"col-3\">\r\n			<span class=\"float-end\">{$inlinemodcol}</span>\r\n			&nbsp;<a href=\"{$sorturl}&amp;sortby=lastpost&amp;order=desc\" class=\"d-none d-sm-none d-md-none d-lg-inline-block d-xl-inline-block d-xxl-inline-block\">{$lang->forumdisplay[\'lastpost\']}</a>\r\n			\r\n		</div>\r\n	</div>\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n\r\n{$announcementlist}\r\n{$threads}\r\n\r\n{$forumsort}\r\n\r\n\r\n<div class=\"mt-3\">{$multipage}</div>\r\n\r\n\r\n\r\n<div class=\"row mt-5 m-0 p-0 border-top border-bottom\">\r\n	<div class=\"col-lg-4 align-self-center py-3\">\r\n		{$searchforum}\r\n	</div>\r\n	<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n		&nbsp;\r\n	</div>\r\n{$inlinemod}\r\n</div>\r\n\r\n{$inline_edit_js}','2','1837','','1720609281');
