INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1100','index','<html>\r\n<head>\r\n<title>{$SITENAME}</title>\r\n\r\n\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n	lang.no_new_posts = \"{$lang->index[\'no_new_posts\']}\";\r\n	lang.click_mark_read = \"{$lang->index[\'click_mark_read\']}\";\r\n// -->\r\n</script>\r\n	<style type=\"text/css\">\r\n		\r\n		.navigation {\r\n			display: none;\r\n		}\r\n		\r\n	</style>\r\n</head>\r\n<body>\r\n\r\n\r\n	\r\n	<div class=\"container-md\">\r\n		\r\n\r\n		\r\n\r\n	\r\n	\r\n<div class=\"mt-4\">\r\n{$forums}\r\n		</div>\r\n\r\n		\r\n		\r\n		<!-- online -->\r\n				<div class=\"card border shadow-none mb-3\">\r\n<div class=\"row ps-0 m-0 py-3\">\r\n		<div class=\"col-auto  align-self-center text-center ps-3 pe-0\">\r\n			<i class=\"fa-solid fa-globe fs-icon text-muted\"></i>\r\n		</div>\r\n		<div class=\"col border-bottom align-self-center text-start ms-3 ps-0 me-3\">\r\n			<h6 class=\"mb-2 fs-6\"><a href=\"{$BASEURL}/online.php\">{$lang->index[\'whos_online\']}</a></h6>\r\n			\r\n				</div>\r\n	</div>\r\n	\r\n	<div class=\"row ps-0 m-0 py-3 pt-0\">\r\n		<div class=\"col-auto  align-self-center text-center ps-3 pe-0\">\r\n			<i class=\"fa-solid fa-chart-column fs-icon text-white\"></i>\r\n		</div>\r\n		<div class=\"col align-self-center text-start ms-3 pt-0 ps-0\">\r\n			{$whosonline}\r\n{$birthdays}\r\n			\r\n				</div>\r\n	</div>\r\n			</div>\r\n		<!-- boardstats -->\r\n		{$boardstats}\r\n	\r\n		\r\n	</div>\r\n	\r\n	\r\n		\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
