INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1107','managegroup','<html>\r\n<head>\r\n	<title>{$mybb->settings[\'bbname\']} - {$lang->members_of}</title>\r\n	{$headerinclude}\r\n</head>\r\n<body>\r\n	{$header}\r\n		<div class=\"container-md\">\r\n			{$multipage}\r\n		<div class=\"card mb-4\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n		{$lang->members_of}\r\n	</div>\r\n	<div class=\"card-body\">\r\n\r\n	<p class=\"text-desc\"><i class=\"fa-solid fa-circle-info\"></i> {$usergrouptype}<br /></p>\r\n	\r\n	\r\n			{$users}\r\n	{$joinrequests}\r\n		\r\n	<form method=\"post\" action=\"managegroup.php\">\r\n		<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n		<input type=\"hidden\" name=\"action\" value=\"do_manageusers\" />\r\n		<input type=\"hidden\" name=\"gid\" value=\"{$gid}\" />\r\n		</div>\r\n		<div class=\"card-footer text-center\">\r\n		{$remove_users}\r\n		</div>\r\n			</div>\r\n		\r\n	\r\n	{$add_user}\r\n	{$invite_user}\r\n			</div>\r\n			</form>\r\n	{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1108','managegroup_adduser','<form method=\"post\" action=\"managegroup.php\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"do_add\" />\r\n<input type=\"hidden\" name=\"gid\" value=\"{$gid}\" />\r\n	\r\n	<div class=\"card mb-4\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n		{$lang->add_member}\r\n	</div>\r\n	<div class=\"card-body\">\r\n		\r\n		<label>{$lang->username}</label>\r\n    <input type=\"text\" id=\"username\" class=\"form-control border form-control-sm\" name=\"username\" size=\"40\" maxlength=\"{$mybb->settings[\'maxnamelength\']}\" /></td>\r\n\r\n<link rel=\"stylesheet\" href=\"{$mybb->asset_url}/jscripts/select2/select2-2.css?ver=1807\">\r\n<script type=\"text/javascript\" src=\"{$mybb->asset_url}/jscripts/select2/select2.min.js?ver=1806\"></script>\r\n<script type=\"text/javascript\">\r\n<!--\r\nif(use_xmlhttprequest == \"1\")\r\n{\r\n	MyBB.select2();\r\n	$(\"#username\").select2({\r\n		placeholder: \"{$lang->search_user}\",\r\n		minimumInputLength: 2,\r\n		multiple: false,\r\n		allowClear: true,\r\n		ajax: { // instead of writing the function to execute the request we use Select2\'s convenient helper\r\n			url: \"xmlhttp.php?action=get_users\",\r\n			dataType: \'json\',\r\n			data: function (term, page) {\r\n				return {\r\n					query: term, // search term\r\n				};\r\n			},\r\n			results: function (data, page) { // parse the results into the format expected by Select2.\r\n				// since we are using custom formatting functions we do not need to alter remote JSON data\r\n				return {results: data};\r\n			}\r\n		},\r\n		initSelection: function(element, callback) {\r\n			var value = $(element).val();\r\n			if (value !== \"\") {\r\n				callback({\r\n					id: value,\r\n					text: value\r\n				});\r\n			}\r\n		},\r\n	});\r\n}\r\n// -->\r\n</script>\r\n		\r\n	</div>\r\n\r\n<div class=\"card-footer text-center\"><input type=\"submit\" class=\"btn btn-primary\" value=\"{$lang->add_member_submit}\" />\r\n	</div></div>\r\n</form>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1109','managegroup_inviteuser','<form method=\"post\" action=\"managegroup.php\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"do_invite\" />\r\n<input type=\"hidden\" name=\"gid\" value=\"{$gid}\" />\r\n	\r\n	<div class=\"card mb-4\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n		{$lang->invite_member}\r\n	</div>\r\n	<div class=\"card-body\">\r\n		\r\n		<label>{$lang->username}</label>\r\n   <input type=\"text\" id=\"inviteusername\" class=\"form-control border form-control-sm\" name=\"inviteusername\" size=\"40\" maxlength=\"{$mybb->settings[\'maxnamelength\']}\" />\r\n<link rel=\"stylesheet\" href=\"{$mybb->asset_url}/jscripts/select2/select2-2.css?ver=1807\">\r\n<script type=\"text/javascript\" src=\"{$mybb->asset_url}/jscripts/select2/select2.min.js?ver=1806\"></script>\r\n<script type=\"text/javascript\">\r\n<!--\r\nif(use_xmlhttprequest == \"1\")\r\n{\r\n	MyBB.select2();\r\n	$(\"#inviteusername\").select2({\r\n		placeholder: \"{$lang->search_user}\",\r\n		minimumInputLength: 2,\r\n		multiple: false,\r\n		allowClear: true,\r\n		ajax: { // instead of writing the function to execute the request we use Select2\'s convenient helper\r\n			url: \"xmlhttp.php?action=get_users\",\r\n			dataType: \'json\',\r\n			data: function (term, page) {\r\n				return {\r\n					query: term, // search term\r\n				};\r\n			},\r\n			results: function (data, page) { // parse the results into the format expected by Select2.\r\n				// since we are using custom formatting functions we do not need to alter remote JSON data\r\n				return {results: data};\r\n			}\r\n		},\r\n		initSelection: function(element, callback) {\r\n			var value = $(element).val();\r\n			if (value !== \"\") {\r\n				callback({\r\n					id: value,\r\n					text: value\r\n				});\r\n			}\r\n		},\r\n	});\r\n}\r\n// -->\r\n</script>\r\n		\r\n	</div>\r\n\r\n<div class=\"card-footer text-center\"><input type=\"submit\" class=\"btn btn-primary\" value=\"{$lang->invite_member_submit}\" />\r\n	</div></div>\r\n</form>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1110','managegroup_joinrequests','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->join_requests}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n	{$header}\r\n		<div class=\"container-md\">\r\n			<form method=\"post\" action=\"managegroup.php\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"do_joinrequests\" />\r\n<input type=\"hidden\" name=\"gid\" value=\"{$gid}\" />\r\n		<div class=\"card\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n		{$joinrequests}\r\n	</div>\r\n	<div class=\"card-body\">\r\n\r\n{$users}\r\n		\r\n				</div>\r\n				<div class=\"card-footer text-center\">\r\n\r\n<input type=\"submit\" class=\"btn btn-primary\" value=\"{$lang->action_requests}\" />\r\n	</div>\r\n					</form>\r\n	</div></div>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1111','managegroup_joinrequests_request','<h6 class=\"mb-0 text-16\">{$user[\'profilelink\']}</h6>\r\n	{$user[\'reason\']}\r\n	\r\n	<div class=\"mt-3\">\r\n		\r\n		<div class=\"form-check form-check-inline\">\r\n  <input type=\"radio\" class=\"form-check-input\" name=\"request[{$user[\'uid\']}]\" value=\"accept\" />\r\n  <label class=\"form-check-label\" for=\"inlineRadio1\">{$lang->accept}</label>\r\n</div>\r\n		\r\n		<div class=\"form-check form-check-inline\">\r\n  <input type=\"radio\" class=\"form-check-input\" name=\"request[{$user[\'uid\']}]\" value=\"ignore\" checked=\"checked\" />\r\n  <label class=\"form-check-label\" for=\"inlineRadio1\">{$lang->ignore}</label>\r\n</div>\r\n		\r\n		<div class=\"form-check form-check-inline\">\r\n  <input type=\"radio\" class=\"form-check-input\" name=\"request[{$user[\'uid\']}]\" value=\"decline\" />\r\n  <label class=\"form-check-label\" for=\"inlineRadio1\">{$lang->decline}</label>\r\n</div>\r\n		\r\n	</div>','2','1837','','1720609281');
