INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1136','member_profile_away','<div class=\"card mb-4\">\r\n	<div class=\"card-body\">\r\n	<h6 class=\"mb-3\"><i class=\"fa-solid fa-circle-info\"></i> {$lang->away_note}</h6>\r\n	<div class=\"mb-3\">{$awayreason}</div>\r\n    {$lang->away_since} {$awaydate} &mdash; {$lang->away_returns} {$returndate}\r\n</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1137','member_profile_banned','<div class=\"card-clean p-3 mb-4\" style=\"border-left:4px solid #dc3545;\">\r\n  <div class=\"d-flex align-items-start gap-3\">\r\n    <div class=\"text-danger\" style=\"font-size:1.5rem;\">\r\n      <i class=\"fa-solid fa-ban\" aria-hidden=\"true\"></i>\r\n    </div>\r\n\r\n    <div class=\"flex-grow-1\">\r\n      <div class=\"d-flex justify-content-between flex-wrap gap-2\">\r\n        <h5 class=\"mb-1 text-danger fw-semibold\">{$lang->member[\'ban_note\']}</h5>\r\n        <span class=\"badge-soft\" style=\"background:#ffe6e6;border-color:#ffc9c9;color:#b02a37;\">\r\n          <i class=\"fa-regular fa-clock me-1\"></i> {$banlength}\r\n        </span>\r\n      </div>\r\n\r\n      <div class=\"mt-2 small muted\">\r\n        <strong>{$lang->global[\'banned_warning2\']}</strong>\r\n      </div>\r\n\r\n      <!-- Причина -->\r\n      <div class=\"mt-2 p-2 rounded small\" style=\"background:#fff5f5;border:1px solid #f8d7da;\">\r\n        {$memban[\'reason\']}\r\n      </div>\r\n\r\n      <!-- Метаданные -->\r\n      <div class=\"mt-2 small muted\">\r\n        <span class=\"me-3\">\r\n          <i class=\"fa-solid fa-user-shield me-1\"></i>\r\n          <strong>{$lang->member[\'ban_by\']}</strong>\r\n          <span class=\"links\">{$memban[\'adminuser\']}</span>\r\n        </span>\r\n        <span>\r\n          <i class=\"fa-regular fa-hourglass-half me-1\"></i>\r\n          <strong>{$lang->member[\'ban_length\']}</strong> {$banlength}\r\n          <span class=\"ms-1\">{$timeremaining}</span>\r\n        </span>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1138','member_profile_contact_details','<div class=\"card-clean mb-4 hov-soft\">\r\n  <div class=\"p-3 border-bottom text-19 fw-bold d-flex align-items-center gap-2\">\r\n    <i class=\"bi bi-person-lines-fill\"></i>\r\n    <span>Contact Details</span>\r\n  </div>\r\n\r\n  <div class=\"p-3\">\r\n    <div class=\"list-row\">\r\n      <span class=\"muted d-flex align-items-center gap-2\">\r\n        <i class=\"bi bi-envelope-fill\"></i>\r\n        <span>Private Message</span>\r\n      </span>\r\n      <span>{$sendpm}</span>\r\n    </div>\r\n\r\n    <div class=\"list-row\">\r\n      <span class=\"muted d-flex align-items-center gap-2\">\r\n        <i class=\"bi bi-at\"></i>\r\n        <span>Email</span>\r\n      </span>\r\n      <span>{$sendemail}</span>\r\n    </div>\r\n\r\n  </div>\r\n</div>','2','1837','','1720609281');
