INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1197','misc_whoposted','<div class=\"modal p-0 m-0\">\r\n		<div class=\"card border\" style=\"overflow-y: auto; max-height: 500px;\">\r\n			<div class=\"card-header text-19 fw-bold border-0 py-3\">{$lang->total_posts} {$numposts}</div>\r\n			<div class=\"card-body\">	<div class=\"row g-0 border-bottom py-2\">\r\n			<div class=\"col\">\r\n<a href=\"javascript:void(0)\"  onclick=\"MyBB.whoPosted({$thread[\'tid\']}, \'username\'); return false;\" class=\"links\">{$lang->user}</a></div>\r\n			<div class=\"col\">\r\n				<a href=\"javascript:void(0)\"  onclick=\"MyBB.whoPosted({$thread[\'tid\']}); return false;\" class=\"links\">{$lang->num_posts}</a>\r\n			</div>\r\n		</div>\r\n{$whoposted}</div>\r\n			<div class=\"card-footer text-center modal_buttons\">{$lang->total_posts} {$numposts}</div>\r\n	</div>\r\n</div>','2','1837','','1720609281');
