INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1210','modcp_announcements_new','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->modcp[\'add_announcement\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n	<form action=\"modcp.php\" method=\"post\" enctype=\"multipart/form-data\">\r\n	<input type=\"hidden\" name=\"action\" value=\"do_new_announcement\" />\r\n	<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	<input type=\"hidden\" name=\"fid\" value=\"{$announcement_fid}\" />\r\n		<div class=\"container-md\">\r\n		\r\n		<div class=\"row\">\r\n			\r\n			<div class=\"col-lg-3\">\r\n\r\n{$modcp_nav}\r\n			</div>\r\n			<div class=\"col\">\r\n					{$errors}\r\n					{$preview}\r\n					<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"pb-4 mb-3 border-bottom\">\r\n<label>{$lang->modcp[\'title\']}</label>\r\n	<input type=\"text\" class=\"form-control border\" name=\"title\" size=\"40\" value=\"{$title}\" />\r\n	</div>\r\n	\r\n	\r\n	\r\n	<div class=\"pb-4 mb-3 border-bottom\">\r\n						<label>{$lang->modcp[\'start_date\']}</label>\r\n						<div class=\"row g-1\">\r\n							<div class=\"col-lg-3 align-self-center\">\r\n								<select name=\"starttime_day\" class=\"form-select border form-select-sm pe-5\">\r\n								{$startdateday}\r\n								</select>\r\n							</div>\r\n							<div class=\"col-lg-3 align-self-center\">\r\n								<select name=\"starttime_month\" class=\"form-select border form-select-sm pe-5\">\r\n								{$startdatemonth}\r\n								</select>\r\n							</div>\r\n							<div class=\"col-lg-3 align-self-center\">\r\n								<input type=\"text\" name=\"starttime_year\" value=\"{$startdateyear}\" size=\"4\" maxlength=\"4\" class=\"form-control border form-control-sm\" />\r\n							</div>\r\n							<div class=\"col-lg-3 align-self-center\">\r\n						<input type=\"text\" name=\"starttime_time\" value=\"{$starttime_time}\" size=\"10\" class=\"form-control border form-control-sm\" placeholder=\"{$lang->modcp[\'time\']}\" />\r\n							</div>\r\n						</div>\r\n	</div>\r\n	\r\n						\r\n							<input type=\"radio\" class=\"form-check-input\" name=\"endtime_type\" id=\"1\" value=\"1\"{$end_type_sel[\'finite\']} />\r\n							<label for=\"1\">{$lang->modcp[\'end_date\']}</label>\r\n	<div class=\"pb-2 mb-3 border-bottom\">\r\n						<div class=\"row g-1\">\r\n							<div class=\"col-lg-3 align-self-center\">\r\n								<select name=\"endtime_day\" class=\"form-select border form-select-sm pe-5\">\r\n								{$enddateday}\r\n								</select>\r\n							</div>\r\n							<div class=\"col-lg-3 align-self-center\">\r\n								<select name=\"endtime_month\" class=\"form-select border form-select-sm pe-5\">\r\n								{$enddatemonth}\r\n								</select>\r\n							</div>\r\n							<div class=\"col-lg-3 align-self-center\">\r\n								<input type=\"text\" name=\"endtime_year\" value=\"{$enddateyear}\" size=\"4\" maxlength=\"4\" class=\"form-control border form-control-sm\" />\r\n							</div>\r\n							<div class=\"col-lg-3 align-self-center\">\r\n								<input type=\"text\" name=\"endtime_time\" value=\"{$endtime_time}\" size=\"10\" class=\"form-control border form-control-sm\" placeholder=\"{$lang->modcp[\'time\']}\" />\r\n							</div>\r\n							<div class=\"mt-2\"><input type=\"radio\" class=\"form-check-input\" name=\"endtime_type\" value=\"2\"{$end_type_sel[\'infinite\']} /> {$lang->modcp[\'never\']}</div>\r\n						</div>\r\n	</div>\r\n\r\n							\r\n							\r\n							{$codebuttons}\r\n						\r\n						<div class=\"row\">\r\n									<div class=\"col-auto\">\r\n						\r\n	\r\n	                    <div class=\"radio-toolbar\">\r\n							\r\n						\r\n							\r\n							\r\n							\r\n							\r\n	</div>\r\n										   </div>\r\n							<div class=\"col-auto\">\r\n	\r\n	\r\n	                    <div class=\"radio-toolbar\">\r\n							\r\n						 \r\n							\r\n	</div>\r\n							</div>\r\n							\r\n	</div>\r\n						</div>\r\n					\r\n					<div class=\"card-footer text-center\">\r\n						<button type=\"submit\" class=\"btn btn-primary\" name=\"preview\" value=\"{$lang->modcp[\'preview\']}\"><i class=\"fa-solid fa-pencil\"></i> &nbsp;{$lang->modcp[\'preview\']}</button> &nbsp;<button type=\"submit\" class=\"btn btn-primary\" value=\"{$lang->modcp[\'add_announcement\']}\"><i class=\"fa-solid fa-check\"></i> &nbsp;{$lang->modcp[\'add_announcement\']}</button>\r\n						\r\n					</div>\r\n			</div>\r\n	</form>\r\n	</div></div>\r\n</div></div>\r\n</div>\r\n	\r\n</body>\r\n</html>','2','1837','','1720609281');
