INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1290','moderation_delayedmodaction_notes','{$delayedmod[\'profilelink\']}</div>\r\n    <div class=\"col-lg align-self-center\">{$delayedmod[\'dateline\']}</div>\r\n    <div class=\"col-lg align-self-center\">{$delayedmod[\'action\']}</div>\r\n    <div class=\"col-lg align-self-center\">{$info}</div>\r\n    <div class=\"col-lg align-self-center\"><a href=\"moderation.php?action=cancel_delayedmoderation&amp;tid={$tid}&amp;fid={$fid}&amp;did={$delayedmod[\'did\']}&amp;my_post_key={$mybb->post_code}\">Cancel</a></div>\r\n</div>','2','1837','','1720609281');
