INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1291','moderation_delayedmoderation','\r\n<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <title>{$mybb->settings[\'bbname\']} - {$lang->delayed_moderation}</title>\r\n   \r\n    \r\n    <style>\r\n   \r\n        \r\n        .card {\r\n            border: none;\r\n            box-shadow: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);\r\n            margin-bottom: 20px;\r\n        }\r\n        \r\n        .card-footer {\r\n            background: #0d6efd;\r\n            color: white;\r\n            font-weight: 600;\r\n            border: none;\r\n        }\r\n        \r\n        .form-select, .form-control {\r\n            border: 1px solid #dee2e6;\r\n        }\r\n        \r\n        .form-check-input:checked {\r\n            background-color: #0d6efd;\r\n            border-color: #0d6efd;\r\n        }\r\n        \r\n        .btn-primary {\r\n            background: #0d6efd;\r\n            border: none;\r\n            padding: 10px 30px;\r\n            font-weight: 600;\r\n        }\r\n        \r\n        .btn-primary:hover {\r\n            background: #0b5ed7;\r\n            transform: translateY(-1px);\r\n            transition: all 0.2s;\r\n        }\r\n        \r\n        .row-header {\r\n            background: #f8f9fa;\r\n            font-weight: 600;\r\n            padding: 10px 0;\r\n            border-bottom: 2px solid #dee2e6;\r\n        }\r\n        \r\n        @media (max-width: 768px) {\r\n            .row-header {\r\n                display: none !important;\r\n            }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container mt-3\">\r\n        {$display_errors}\r\n        \r\n        <!-- Current Delayed Moderation Queue -->\r\n        <div class=\"card mb-4\">\r\n            <div class=\"card-footer\">\r\n                {$lang->moderation[\'delayed_mod_queue\']}\r\n            </div>\r\n            <div class=\"card-body pt-0 pb-0\">\r\n                <!-- Header for large screens -->\r\n                <div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n                    <div class=\"row row-header\">\r\n                        <div class=\"col align-self-center\">{$lang->mod_username}</div>\r\n                        <div class=\"col align-self-center\">{$lang->time_to_perform_action}</div>\r\n                        <div class=\"col align-self-center\">{$lang->mod_actions}</div>\r\n                        <div class=\"col align-self-center\">{$lang->mod_information}</div>\r\n                        <div class=\"col align-self-center\">{$lang->actions}</div>\r\n                    </div>\r\n                </div>\r\n                \r\n                {$delayedmods}\r\n            </div>\r\n        </div>\r\n        \r\n        <!-- Add New Delayed Moderation Form -->\r\n        <form action=\"moderation.php\" method=\"post\" id=\"delayedModForm\">\r\n            <input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n            <input type=\"hidden\" name=\"action\" value=\"do_delayedmoderation\" />\r\n            <input type=\"hidden\" name=\"url\" value=\"{$url}\" />\r\n            <input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n            <input type=\"hidden\" name=\"fid\" value=\"{$fid}\" />\r\n            \r\n            <!-- Delayed Moderation Settings -->\r\n            <div class=\"card mb-4\">\r\n                <div class=\"card-footer\">\r\n                    {$lang->moderation[\'delayed_moderation\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    <div class=\"text-desc mb-3\">{$lang->moderation[\'delayed_moderation_desc\']}</div>\r\n                    \r\n                    {$loginbox}\r\n                    \r\n                    <strong>{$threads}</strong>\r\n                    \r\n                    <div class=\"mt-3\">\r\n                        <div class=\"mb-2\">{$lang->moderation[\'run_moderation_time\']}</div>\r\n                        <div class=\"row g-2 align-items-center\">\r\n                            <div class=\"col-auto\">\r\n                                <select name=\"date_day\" class=\"form-select form-select-sm w-auto\">\r\n                                    {$dateday}\r\n                                </select>\r\n                            </div>\r\n                            <div class=\"col-auto\">\r\n                                <select name=\"date_month\" class=\"form-select form-select-sm w-auto\">\r\n                                    {$datemonth}\r\n                                </select>\r\n                            </div>\r\n                            <div class=\"col-auto\">\r\n                                <input type=\"text\" name=\"date_year\" value=\"{$dateyear}\" size=\"4\" maxlength=\"4\" class=\"form-control form-control-sm\" placeholder=\"Year\" />\r\n                            </div>\r\n                            <div class=\"col-auto\">\r\n                                <span class=\"text-muted\">{$lang->moderation[\'time\']}</span>\r\n                            </div>\r\n                            <div class=\"col-auto\">\r\n                                <input type=\"text\" name=\"date_time\" value=\"{$datetime}\" size=\"10\" class=\"form-control form-control-sm\" placeholder=\"HH:MM\" />\r\n                            </div>\r\n                            <div class=\"col-12 mt-2\">\r\n                                <small class=\"text-muted\">Format: Day Month Year Time (e.g., 15 12 2023 14:30)</small>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            \r\n            <!-- Moderation Action Selection -->\r\n            <div class=\"card mb-4\">\r\n                <div class=\"card-footer\">\r\n                    {$lang->moderation[\'moderation_action\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    <script type=\"text/javascript\">\r\n                    function toggleType() {\r\n                        // Move/Copy Thread section\r\n                        var moveCopyRadio = document.getElementById(\'type_movecopythread\');\r\n                        var moveCopySection = document.getElementById(\'type_movecopythread_expanded\');\r\n                        \r\n                        // Merge Threads section (if exists)\r\n                        var mergeRadio = document.getElementById(\'type_merge\');\r\n                        var mergeSection = document.getElementById(\'type_merge_expanded\');\r\n                        \r\n                        if (moveCopySection) {\r\n                            if (moveCopyRadio && moveCopyRadio.checked) {\r\n                                moveCopySection.style.display = \'block\';\r\n                                if (mergeSection) mergeSection.style.display = \'none\';\r\n                            } else if (mergeRadio && mergeRadio && mergeRadio.checked) {\r\n                                if (moveCopySection) moveCopySection.style.display = \'none\';\r\n                                if (mergeSection) mergeSection.style.display = \'block\';\r\n                            } else {\r\n                                if (moveCopySection) moveCopySection.style.display = \'none\';\r\n                                if (mergeSection) mergeSection.style.display = \'none\';\r\n                            }\r\n                        }\r\n                    }\r\n                    \r\n                    // Add event listeners to all radio buttons\r\n                    document.addEventListener(\'DOMContentLoaded\', function() {\r\n                        // Get all radio buttons with name=\"type\"\r\n                        var typeRadios = document.querySelectorAll(\'input[name=\"type\"]\');\r\n                        \r\n                        // Add change event listener to each radio button\r\n                        typeRadios.forEach(function(radio) {\r\n                            radio.addEventListener(\'change\', toggleType);\r\n                        });\r\n                        \r\n                        // Initial call to set correct state\r\n                        toggleType();\r\n                    });\r\n                    </script>\r\n                    \r\n                    <div style=\"margin-top: 0; margin-bottom: 0; width: 100%; font-weight: normal\">\r\n                        {$openclosethread}\r\n                        {$deletethread}\r\n                        {$stickunstickthread}\r\n                        \r\n                        <!-- Move/Copy Thread Option -->\r\n                        <div class=\"mb-2\">\r\n                            <input type=\"radio\" name=\"type\" class=\"form-check-input\" value=\"move\" {$type_selected[\'move\']} id=\"type_movecopythread\" />\r\n                            <label for=\"type_movecopythread\" class=\"form-check-label\">{$lang->moderation[\'move_copy_thread\']}</label>\r\n                        </div>\r\n                        \r\n                        <!-- Move/Copy Thread Expanded Section -->\r\n                        <div style=\"margin-top: 4px;\" id=\"type_movecopythread_expanded\" class=\"py-3 border-top border-bottom mt-3 mb-3\" style=\"display: none;\">\r\n                            <div class=\"mb-2\">\r\n                                <label class=\"form-label\">{$lang->moderation[\'new_forum\']}</label>\r\n                                {$forumselect}\r\n                            </div>\r\n                            {$moderation_delayedmoderation_move}\r\n                        </div>\r\n                        \r\n                        <!-- Merge Threads (if exists) -->\r\n                        {$moderation_delayedmoderation_merge}\r\n                        \r\n                        <!-- Other Options -->\r\n                        <div class=\"mb-2\">\r\n                            <input type=\"radio\" name=\"type\" class=\"form-check-input\" value=\"removeredirects\" {$type_selected[\'removeredirects\']} id=\"type_removeredirects\" />\r\n                            <label for=\"type_removeredirects\" class=\"form-check-label\">{$lang->moderation[\'remove_redirects\']}</label>\r\n                        </div>\r\n                        \r\n                        <div class=\"mb-2\">\r\n                            <input type=\"radio\" name=\"type\" class=\"form-check-input\" value=\"removesubscriptions\" {$type_selected[\'removesubscriptions\']} id=\"type_removesubscriptions\" />\r\n                            <label for=\"type_removesubscriptions\" class=\"form-check-label\">{$lang->moderation[\'remove_subscriptions\']}</label>\r\n                        </div>\r\n                        \r\n                        {$approveunapprovethread}\r\n                        {$customthreadtools}\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"card-footer text-center\">\r\n                    <button type=\"submit\" class=\"btn btn-primary\">\r\n                        <i class=\"fas fa-calendar-plus me-2\"></i>\r\n                        {$lang->moderation[\'save_delayed_moderation\']}\r\n                    </button>\r\n                </div>\r\n            </div>\r\n        </form>\r\n    </div>\r\n    \r\n    <script>\r\n    // Form validation\r\n    document.getElementById(\'delayedModForm\')?.addEventListener(\'submit\', function(e) {\r\n        var dateYear = this.querySelector(\'input[name=\"date_year\"]\');\r\n        var dateTime = this.querySelector(\'input[name=\"date_time\"]\');\r\n        var typeRadios = this.querySelectorAll(\'input[name=\"type\"]:checked\');\r\n        var hasError = false;\r\n        \r\n        // Check if a moderation type is selected\r\n        if (typeRadios.length === 0) {\r\n            alert(\'Please select a moderation action.\');\r\n            e.preventDefault();\r\n            return false;\r\n        }\r\n        \r\n        // Validate date year\r\n        if (dateYear && dateYear.value) {\r\n            var year = parseInt(dateYear.value);\r\n            var currentYear = new Date().getFullYear();\r\n            \r\n            if (isNaN(year) || year < currentYear || year > currentYear + 10) {\r\n                alert(\'Please enter a valid year (current year to \' + (currentYear + 10) + \').\');\r\n                dateYear.focus();\r\n                e.preventDefault();\r\n                return false;\r\n            }\r\n        }\r\n        \r\n        // Validate time format\r\n        if (dateTime && dateTime.value) {\r\n            var timeRegex = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;\r\n            if (!timeRegex.test(dateTime.value)) {\r\n                alert(\'Please enter time in HH:MM format (24-hour).\');\r\n                dateTime.focus();\r\n                e.preventDefault();\r\n                return false;\r\n            }\r\n        }\r\n        \r\n        // If moving threads, check if forum is selected\r\n        var moveRadio = document.getElementById(\'type_movecopythread\');\r\n        if (moveRadio && moveRadio.checked) {\r\n            var forumSelect = this.querySelector(\'select[name=\"fid\"]\');\r\n            if (forumSelect && !forumSelect.value) {\r\n                alert(\'Please select a destination forum for thread move/copy.\');\r\n                forumSelect.focus();\r\n                e.preventDefault();\r\n                return false;\r\n            }\r\n        }\r\n        \r\n        // Confirm submission\r\n        if (!confirm(\'Schedule this moderation action for the specified date and time?\')) {\r\n            e.preventDefault();\r\n            return false;\r\n        }\r\n        \r\n        // Show loading state\r\n        var submitBtn = this.querySelector(\'button[type=\"submit\"]\');\r\n        if (submitBtn) {\r\n            submitBtn.disabled = true;\r\n            submitBtn.innerHTML = \'<i class=\"fas fa-spinner fa-spin me-2\"></i> Saving...\';\r\n        }\r\n        \r\n        return true;\r\n    });\r\n    \r\n    // Real-time validation for date inputs\r\n    document.addEventListener(\'DOMContentLoaded\', function() {\r\n        var dateYear = document.querySelector(\'input[name=\"date_year\"]\');\r\n        var dateTime = document.querySelector(\'input[name=\"date_time\"]\');\r\n        \r\n        if (dateYear) {\r\n            dateYear.addEventListener(\'input\', function() {\r\n                var value = this.value.replace(/[^0-9]/g, \'\');\r\n                if (value.length > 4) {\r\n                    value = value.substring(0, 4);\r\n                }\r\n                this.value = value;\r\n                \r\n                // Add visual feedback\r\n                if (value.length === 4) {\r\n                    var year = parseInt(value);\r\n                    var currentYear = new Date().getFullYear();\r\n                    \r\n                    if (year >= currentYear && year <= currentYear + 10) {\r\n                        this.classList.remove(\'is-invalid\');\r\n                        this.classList.add(\'is-valid\');\r\n                    } else {\r\n                        this.classList.remove(\'is-valid\');\r\n                        this.classList.add(\'is-invalid\');\r\n                    }\r\n                } else {\r\n                    this.classList.remove(\'is-valid\', \'is-invalid\');\r\n                }\r\n            });\r\n        }\r\n        \r\n        if (dateTime) {\r\n            dateTime.addEventListener(\'input\', function() {\r\n                var value = this.value;\r\n                // Allow only numbers and colon\r\n                value = value.replace(/[^0-9:]/g, \'\');\r\n                \r\n                // Auto-insert colon after 2 digits\r\n                if (value.length === 2 && !value.includes(\':\')) {\r\n                    value = value + \':\';\r\n                }\r\n                \r\n                // Limit to 5 characters (HH:MM)\r\n                if (value.length > 5) {\r\n                    value = value.substring(0, 5);\r\n                }\r\n                \r\n                this.value = value;\r\n                \r\n                // Validate format\r\n                var timeRegex = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;\r\n                if (timeRegex.test(value)) {\r\n                    this.classList.remove(\'is-invalid\');\r\n                    this.classList.add(\'is-valid\');\r\n                } else if (value.length >= 3) {\r\n                    this.classList.remove(\'is-valid\');\r\n                    this.classList.add(\'is-invalid\');\r\n                } else {\r\n                    this.classList.remove(\'is-valid\', \'is-invalid\');\r\n                }\r\n            });\r\n        }\r\n    });\r\n    </script>\r\n</body>\r\n</html>\r\n','2','1837','','1720609281');
