INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1301','moderation_deletepoll','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->delete_poll}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n\r\n	<div class=\"mb-3 text-muted ps-3 pe-3\">{$lang->delete_poll}</div>\r\n\r\n	<div class=\"ps-3 pe-3\">{$loginbox}</div>\r\n\r\n<div class=\"mt-3 text-end ps-3 pe-3\"><input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->delete_poll}\" /></div>\r\n<input type=\"hidden\" name=\"action\" value=\"do_deletepoll\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n<input type=\"hidden\" name=\"delete\" value=\"1\" />\r\n	</div>\r\n		</div>\r\n	</div>\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1302','moderation_deletethread','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->delete_thread}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"legend mb-4\">{$thread[\'subject\']} - {$lang->delete_thread}</div>\r\n\r\n	<div class=\"ps-3 pe-3 mb-3 text-muted\">{$lang->confirm_delete_threads}</div>\r\n\r\n	<div class=\"ps-3 pe-3\">{$loginbox}</div>\r\n\r\n<div class=\"text-end ps-3 pe-3 mt-3\"><input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->delete_thread}\" /></div>\r\n<input type=\"hidden\" name=\"action\" value=\"do_deletethread\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n</form>\r\n		</div></div></div>\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1303','moderation_getip','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->get_post_ip}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"legend mb-4\">{$lang->get_post_ip}</div>\r\n<div class=\"ps-3 pe-3\">{$lang->username} {$username}\r\n	<div class=\"mt-3\"></div>\r\n	{$lang->ip_address} {$post[\'ipaddress\']}\r\n\r\n	<div class=\"mt-3\"></div>\r\n	{$lang->hostname}<br /><span class=\"text-muted\">{$lang->if_resolvable}</span>\r\n	<div class=\"mt-2\"></div>{$hostname}\r\n	<div class=\"mt-3\"></div>\r\n{$modoptions}\r\n	</div></div></div></div>\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1304','moderation_getip_modal','<div class=\"modal bg-white p-5 border-0 shadow-sm rounded\">\r\n	<div style=\"max-height: 500px;\">\r\n<table border=\"0\" cellspacing=\"{$theme[\'borderwidth\']}\" cellpadding=\"{$theme[\'tablespace\']}\" class=\"tborder\">\r\n<tr>\r\n<td class=\"thead\" colspan=\"2\"><strong>{$lang->get_post_ip}</strong></td>\r\n</tr>\r\n<tr>\r\n<td class=\"trow1\" width=\"20%\"><strong>{$lang->username}</strong></td>\r\n<td class=\"trow1\">{$username}</td>\r\n</tr>\r\n<tr>\r\n<td class=\"trow2\"><strong>{$lang->ip_address}</strong></td>\r\n<td class=\"trow2\">{$post[\'ipaddress\']}</td>\r\n</tr>\r\n<tr>\r\n<td class=\"trow1\"><strong>{$lang->hostname}<br /><span class=\"smalltext\">{$lang->if_resolvable}</span></strong></td>\r\n<td class=\"trow2\">{$hostname}</td>\r\n</tr>\r\n{$modoptions}\r\n</table>\r\n</div>\r\n</div>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1305','moderation_getip_modoptions','	<div class=\"legend mb-2\">{$lang->mod_options}</div>\r\n<div class=\"p-3 border border-1 mt-3 mb-3 rounded\">\r\n	<a href=\"modcp.php?action=ipsearch&amp;ipaddress={$ipaddress}&amp;search_users=1\">{$lang->search_ip_users}</a><br />\r\n	<a href=\"modcp.php?action=ipsearch&amp;ipaddress={$ipaddress}&amp;search_posts=1\">{$lang->search_ip_posts}</a><br />\r\n	<a href=\"modcp.php?action=iplookup&ipaddress={$ipaddress}\" onclick=\"MyBB.popupWindow(\'/modcp.php?action=iplookup&ipaddress={$ipaddress}&modal=1\'); return false;\">{$lang->info_on_ip}</a>\r\n	</div>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1306','moderation_getpmip','	<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->get_pm_ip}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"legend mb-4\">{$lang->get_pm_ip}</div>\r\n<div class=\"ps-3 pe-3\">{$lang->username} {$username}\r\n	<div class=\"mt-3\"></div>\r\n	{$lang->ip_address} {$pm[\'ipaddress\']}\r\n\r\n	<div class=\"mt-3\"></div>\r\n	{$lang->hostname}<br /><span class=\"text-muted\">{$lang->if_resolvable}</span>\r\n	<div class=\"mt-2\"></div>{$hostname}\r\n	<div class=\"mt-3\"></div>\r\n{$modoptions}\r\n	</div></div></div></div>\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1307','moderation_getpmip_modal','<div class=\"modal rounded bg-white p-5 shadow-sm\">\r\n	<div style=\"max-height: 500px;\">\r\n<table border=\"0\" cellspacing=\"{$theme[\'borderwidth\']}\" cellpadding=\"{$theme[\'tablespace\']}\" class=\"tborder\">\r\n<tr>\r\n<td class=\"thead\" colspan=\"2\"><strong>{$lang->get_pm_ip}</strong></td>\r\n</tr>\r\n<tr>\r\n<td class=\"trow1\" width=\"20%\"><strong>{$lang->username}</strong></td>\r\n<td class=\"trow1\">{$username}</td>\r\n</tr>\r\n<tr>\r\n<td class=\"trow2\"><strong>{$lang->ip_address}</strong></td>\r\n<td class=\"trow2\">{$pm[\'ipaddress\']}</td>\r\n</tr>\r\n<tr>\r\n<td class=\"trow1\"><strong>{$lang->hostname}<br /><span class=\"smalltext\">{$lang->if_resolvable}</span></strong></td>\r\n<td class=\"trow2\">{$hostname}</td>\r\n</tr>\r\n{$modoptions}\r\n</table>\r\n</div>\r\n</div>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1308','moderation_inline_deleteposts','<html>\r\n<head>\r\n<title>{$SITENAME} - {Delete Posts Permanently}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"legend mb-4\">Delete Posts Permanently</div>\r\n	<div class=\"ps-3 pe-3 mb-3 text-muted\">Are you sure you wish to delete the selected posts from the thread? Once they have been deleted they cannot be restored. If there are no posts left in the thread, the thread will also be deleted</div>\r\n\r\n	<div class=\"ps-3 pe-3 mb-3\">{$loginbox}</div>\r\n\r\n<div class=\"text-end ps-e pe-3\"><input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"Delete Posts Permanently\" /></div>\r\n<input type=\"hidden\" name=\"action\" value=\"do_multideleteposts\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n<input type=\"hidden\" name=\"posts\" value=\"{$inlineids}\" />\r\n<input type=\"hidden\" name=\"url\" value=\"{$return_url}\" />\r\n	</div></div></div>\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1309','moderation_inline_deletethreads','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->delete_threads}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"mb-3 text-desc\">{$lang->confirm_delete_threads}</div>\r\n{$loginbox}\r\n	</div>\r\n<div class=\"card-footer text-center\">\r\n	<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->delete_threads}\"><i class=\"fa-solid fa-check\"></i> &nbsp;{$lang->delete_threads}</button>\r\n<input type=\"hidden\" name=\"action\" value=\"do_multideletethreads\" />\r\n<input type=\"hidden\" name=\"fid\" value=\"{$fid}\" />\r\n<input type=\"hidden\" name=\"threads\" value=\"{$inlineids}\" />\r\n<input type=\"hidden\" name=\"url\" value=\"{$return_url}\" />\r\n	</div></div></div>\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1310','moderation_inline_mergeposts','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->merge_posts}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n{$loginbox}\r\n	<label>{$lang->post_separator}</label>\r\n	\r\n	<div class=\"radio-toolbar\">\r\n<input type=\"radio\" name=\"sep\" id=\"sep\" value=\"hr\" checked=\"checked\" /><label for=\"sep\">{$lang->horizontal_rule}</label>\r\n		<input type=\"radio\" name=\"sep\" id=\"sep2\" value=\"new_line\" /><label for=\"sep2\">{$lang->new_line}</label>\r\n		</div>\r\n\r\n	<div class=\"mt-3\"></div>\r\n{$postlist}\r\n\r\n	</div>\r\n<div class=\"card-footer text-center\"><button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->merge_posts}\"><i class=\"fa-solid fa-shuffle\"></i> &nbsp;{$lang->merge_posts}</button>\r\n	</div>\r\n<input type=\"hidden\" name=\"action\" value=\"do_multimergeposts\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n<input type=\"hidden\" name=\"url\" value=\"{$return_url}\" />\r\n	</div></div>\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1311','moderation_inline_moveposts','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->move_posts}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n{$loginbox}\r\n	\r\n	<div class=\"mb-3 text-desc\">Copy the URL of the thread to move these posts to into the textbox on the right</div>\r\n	<label>Thread to move the posts to:</label>\r\n	<br />\r\n<input type=\"text\" class=\"form-control border form-control-sm\" name=\"threadurl\" size=\"40\" />\r\n\r\n	</div>\r\n<div class=\"card-footer text-center\"><button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"Move Posts\"><i class=\"fa-solid fa-arrow-right\"></i> &nbsp;Move Posts</button>\r\n	</div>\r\n<input type=\"hidden\" name=\"action\" value=\"do_multimoveposts\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n<input type=\"hidden\" name=\"posts\" value=\"{$inlineids}\" />\r\n<input type=\"hidden\" name=\"url\" value=\"{$return_url}\" />\r\n	</div></div>\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1312','moderation_inline_movethreads','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->moderation[\'move_threads\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n{$loginbox}\r\n<div class=\"py-3 mb-3 border-top border-bottom\">\r\n	<label>{$lang->moderation[\'new_forum\']}</label>\r\n	{$forumselect}\r\n	</div>\r\n\r\n	<label>{$lang->moderation[\'method\']}</label>\r\n	\r\n	<br /><br />\r\n\r\n<label class=\"form-check-label\"><input type=\"radio\" class=\"form-check-input\" name=\"method\" value=\"move\" /> {$lang->moderation[\'method_move\']}</label><br />\r\n<label class=\"form-check-label\"><input type=\"radio\" class=\"form-check-input\" name=\"method\" value=\"redirect\" checked=\"checked\" /> {$lang->moderation[\'method_move_redirect\']}</label> <input type=\"text\" class=\"form-control border form-control-sm mt-2 mb-1\" name=\"redirect_expire\" size=\"3\" /> {$lang->moderation[\'redirect_expire_note\']}<br />\r\n<label class=\"form-check-label\"><input type=\"radio\" class=\"form-check-input\" name=\"method\" value=\"copy\" /> {$lang->moderation[\'method_copy\']}</label>\r\n\r\n	</div>\r\n	\r\n<div class=\"card-footer text-center\"><button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->moderation[\'move_threads\']}\"><i class=\"fa-solid fa-arrow-right\"></i> &nbsp;{$lang->moderation[\'move_threads\']}</button>\r\n<input type=\"hidden\" name=\"action\" value=\"do_multimovethreads\" />\r\n<input type=\"hidden\" name=\"fid\" value=\"{$fid}\" />\r\n<input type=\"hidden\" name=\"threads\" value=\"{$inlineids}\" />\r\n<input type=\"hidden\" name=\"url\" value=\"{$return_url}\" />\r\n	</div></div>\r\n	</div>\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1313','moderation_inline_splitposts','<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{$mybb->settings[\'bbname\']} - {$lang->moderation[\'split_thread\']}</title>\r\n    \r\n\r\n    <style>\r\n     \r\n        \r\n        .split-card {\r\n            max-width: 600px;\r\n            width: 100%;\r\n            margin: 0 auto;\r\n            border: none;\r\n            border-radius: 20px;\r\n            overflow: hidden;\r\n            box-shadow: 0 20px 40px rgba(13, 110, 253, 0.2);\r\n            transition: transform 0.3s ease;\r\n        }\r\n        \r\n        .split-card:hover {\r\n            transform: translateY(-5px);\r\n        }\r\n        \r\n        .split-header {\r\n            background: linear-gradient(135deg, #0d6efd 0%, #0a58ca 100%);\r\n            color: white;\r\n            padding: 30px;\r\n            text-align: center;\r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        .split-header::before {\r\n            content: \'\';\r\n            position: absolute;\r\n            top: -50%;\r\n            left: -50%;\r\n           \r\n            background: rgba(255, 255, 255, 0.1);\r\n            transform: rotate(45deg);\r\n        }\r\n        \r\n        .split-icon {\r\n            width: 80px;\r\n            height: 80px;\r\n            background: rgba(255, 255, 255, 0.2);\r\n            border-radius: 50%;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            margin: 0 auto 20px;\r\n            font-size: 36px;\r\n            position: relative;\r\n            z-index: 1;\r\n        }\r\n        \r\n        .post-count {\r\n            font-size: 3rem;\r\n            font-weight: 700;\r\n            color: white;\r\n            text-align: center;\r\n            margin: 20px 0;\r\n        }\r\n        \r\n        .info-box {\r\n            background: linear-gradient(135deg, #e7f1ff 0%, #d0e3ff 100%);\r\n            border-left: 4px solid #0d6efd;\r\n            border-radius: 12px;\r\n            padding: 20px;\r\n            margin: 20px 0;\r\n        }\r\n        \r\n        .input-group-custom {\r\n            position: relative;\r\n            margin-bottom: 20px;\r\n        }\r\n        \r\n        .input-icon {\r\n            position: absolute;\r\n            left: 15px;\r\n            top: 50%;\r\n            transform: translateY(-50%);\r\n            color: #0d6efd;\r\n            z-index: 3;\r\n        }\r\n        \r\n        .form-control-custom {\r\n            padding-left: 45px;\r\n            border: 2px solid #dee2e6;\r\n            border-radius: 10px;\r\n            height: 52px;\r\n            font-size: 1rem;\r\n            transition: all 0.3s ease;\r\n        }\r\n        \r\n        .form-control-custom:focus {\r\n            border-color: #0d6efd;\r\n            box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);\r\n        }\r\n        \r\n        .form-select-custom {\r\n            padding-left: 45px;\r\n            border: 2px solid #dee2e6;\r\n            border-radius: 10px;\r\n            height: 52px;\r\n            font-size: 1rem;\r\n            transition: all 0.3s ease;\r\n            background-image: url(\"data:image/svg+xml,%3csvg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 16 16\'%3e%3cpath fill=\'none\' stroke=\'%230d6efd\' stroke-linecap=\'round\' stroke-linejoin=\'round\' stroke-width=\'2\' d=\'m2 5 6 6 6-6\'/%3e%3c/svg%3e\");\r\n        }\r\n        \r\n        .form-select-custom:focus {\r\n            border-color: #0d6efd;\r\n            box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);\r\n        }\r\n        \r\n        .btn-split {\r\n            background: linear-gradient(135deg, #0d6efd 0%, #0a58ca 100%);\r\n            border: none;\r\n            padding: 14px 35px;\r\n            font-weight: 600;\r\n            font-size: 1.1rem;\r\n            transition: all 0.3s ease;\r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n        \r\n        .btn-split:hover:not(:disabled) {\r\n            transform: translateY(-2px);\r\n            box-shadow: 0 10px 25px rgba(13, 110, 253, 0.3);\r\n        }\r\n        \r\n        .btn-split:active {\r\n            transform: translateY(0);\r\n        }\r\n        \r\n        .btn-split:disabled {\r\n            opacity: 0.6;\r\n            cursor: not-allowed;\r\n        }\r\n        \r\n        .btn-cancel {\r\n            background: #6c757d;\r\n            border: none;\r\n            padding: 12px 30px;\r\n            font-weight: 600;\r\n            transition: all 0.3s ease;\r\n        }\r\n        \r\n        .btn-cancel:hover {\r\n            background: #5a6268;\r\n            transform: translateY(-2px);\r\n            box-shadow: 0 5px 15px rgba(108, 117, 125, 0.3);\r\n        }\r\n        \r\n        .security-box {\r\n            background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);\r\n            border-radius: 12px;\r\n            padding: 20px;\r\n            margin-bottom: 25px;\r\n            border-left: 4px solid #0d6efd;\r\n        }\r\n        \r\n        .ripple {\r\n            position: absolute;\r\n            border-radius: 50%;\r\n            background: rgba(255, 255, 255, 0.6);\r\n            transform: scale(0);\r\n            animation: ripple-animation 0.6s linear;\r\n        }\r\n        \r\n        @keyframes ripple-animation {\r\n            to {\r\n                transform: scale(4);\r\n                opacity: 0;\r\n            }\r\n        }\r\n        \r\n        .thread-info {\r\n            background: white;\r\n            border: 2px solid #e9ecef;\r\n            border-radius: 12px;\r\n            padding: 15px;\r\n            margin-bottom: 20px;\r\n        }\r\n        \r\n        .info-item {\r\n            display: flex;\r\n            align-items: center;\r\n            margin-bottom: 10px;\r\n        }\r\n        \r\n        .info-icon {\r\n            width: 36px;\r\n            height: 36px;\r\n            background: #f0f0f0;\r\n            border-radius: 8px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            margin-right: 12px;\r\n            color: #0d6efd;\r\n        }\r\n        \r\n        .progress-bar-split {\r\n            background: linear-gradient(135deg, #0d6efd 0%, #0a58ca 100%);\r\n        }\r\n        \r\n        .original-thread {\r\n            background: linear-gradient(135deg, #e7f1ff 0%, #d0e3ff 100%);\r\n            border-left: 4px solid #0d6efd;\r\n            border-radius: 10px;\r\n            padding: 15px;\r\n            margin-bottom: 20px;\r\n        }\r\n        \r\n        .alert-warning {\r\n            border-left: 4px solid #ffc107;\r\n        }\r\n        \r\n        .alert-info {\r\n            border-left: 4px solid #0dcaf0;\r\n        }\r\n        \r\n        .card-footer {\r\n            background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container mt-3\">\r\n        <div class=\"split-card\">\r\n            <!-- Header -->\r\n            <div class=\"split-header\">\r\n                <div class=\"split-icon\">\r\n                    <i class=\"fas fa-arrows-split-up-and-left\"></i>\r\n                </div>\r\n                <h1 class=\"h3 mb-2\">{$lang->split_thread}</h1>\r\n                <p class=\"mb-0 opacity-75\">Create a new thread from selected posts</p>\r\n                \r\n                <!-- Posts Count -->\r\n                <div class=\"mt-4\">\r\n                    <div class=\"post-count\">\r\n                        <i class=\"fas fa-comments\"></i>\r\n                        <span id=\"postsCount\">0</span>\r\n                    </div>\r\n                    <p class=\"text-white opacity-75 mb-0\">Posts Selected for Split</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <!-- Form -->\r\n            <form action=\"moderation.php\" method=\"post\" id=\"splitThreadForm\">\r\n                <input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n                <input type=\"hidden\" name=\"action\" value=\"do_multisplitposts\" />\r\n                <input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n                <input type=\"hidden\" name=\"posts\" value=\"{$inlineids}\" />\r\n                <input type=\"hidden\" name=\"url\" value=\"{$return_url}\" />\r\n                \r\n                <div class=\"card-body p-4\">\r\n                    <!-- Security Verification -->\r\n                    <div class=\"security-box\">\r\n                        <h5 class=\"fw-bold mb-3\"><i class=\"fas fa-shield-alt me-2 text-primary\"></i>Security Verification</h5>\r\n                        <div class=\"mb-0\">{$loginbox}</div>\r\n                    </div>\r\n                    \r\n                    <!-- Information Box -->\r\n                    <div class=\"info-box\">\r\n                        <div class=\"d-flex\">\r\n                            <i class=\"fas fa-info-circle fa-2x me-3 mt-1 text-primary\"></i>\r\n                            <div>\r\n                                <h6 class=\"mb-2\">Split Operation Information</h6>\r\n                                <p class=\"mb-0 small\">Selected posts will be moved from the current thread to create a new separate thread.</p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <!-- Original Thread Info -->\r\n                    <div class=\"original-thread\">\r\n                        <h6 class=\"fw-bold mb-2\"><i class=\"fas fa-file-alt me-2 text-primary\"></i>Original Thread</h6>\r\n                        <div class=\"info-item\">\r\n                            <div class=\"info-icon\">\r\n                                <i class=\"fas fa-hashtag\"></i>\r\n                            </div>\r\n                            <div>\r\n                                <div class=\"small text-muted\">Thread ID</div>\r\n                                <div class=\"fw-bold\">#{$tid}</div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <!-- New Thread Information -->\r\n                    <div class=\"mb-4\">\r\n                        <h5 class=\"fw-bold mb-3\"><i class=\"fas fa-plus-circle me-2 text-primary\"></i>{$lang->moderation[\'new_thread_info\']}</h5>\r\n                        \r\n                        <!-- New Subject -->\r\n                        <div class=\"input-group-custom\">\r\n                            <i class=\"fas fa-heading input-icon text-primary\"></i>\r\n                            <label class=\"form-label fw-bold text-primary\">{$lang->new_subject}</label>\r\n                            <input type=\"text\" \r\n                                   class=\"form-control form-control-custom\" \r\n                                   name=\"newsubject\" \r\n                                   value=\"{$lang->moderation[\'split_thread_subject\']} {$thread[\'subject\']}\"\r\n                                   placeholder=\"Enter new thread title\"\r\n                                   required>\r\n                            <div class=\"form-text\">This will be the title of your new thread.</div>\r\n                        </div>\r\n                        \r\n                        <!-- Destination Forum -->\r\n                        <div class=\"input-group-custom\">\r\n                            <i class=\"fas fa-folder input-icon text-primary\"></i>\r\n                            <label class=\"form-label fw-bold text-primary\">{$lang->new_forum}</label>\r\n                            <div class=\"form-select-container\">\r\n                                {$forumselect}\r\n                            </div>\r\n                            <div class=\"form-text\">Select the forum where the new thread will be created.</div>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <!-- Important Notes -->\r\n                    <div class=\"alert alert-warning\">\r\n                        <div class=\"d-flex\">\r\n                            <i class=\"fas fa-exclamation-triangle fa-lg me-3 mt-1 text-warning\"></i>\r\n                            <div>\r\n                                <h6 class=\"alert-heading mb-2\">Important Notes</h6>\r\n                                <ul class=\"mb-0 small\">\r\n                                    <li>Selected posts will be moved to the new thread</li>\r\n                                    <li>Original thread will retain remaining posts</li>\r\n                                    <li>Post order and timestamps will be preserved</li>\r\n                                    <li>Ensure you have proper permissions for the destination forum</li>\r\n                                    <li>This operation affects <strong id=\"postsCount2\">0</strong> post(s)</li>\r\n                                </ul>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                \r\n                <!-- Footer -->\r\n                <div class=\"card-footer bg-light py-4\">\r\n                    <div class=\"d-flex flex-column flex-md-row justify-content-between align-items-center\">\r\n                        <div class=\"mb-3 mb-md-0\">\r\n                            <a href=\"{$return_url}\" class=\"btn btn-cancel text-white\">\r\n                                <i class=\"fas fa-arrow-left me-2\"></i>\r\n                                Cancel & Return\r\n                            </a>\r\n                        </div>\r\n                        \r\n                        <div>\r\n                            <button type=\"submit\" class=\"btn btn-split text-white\" name=\"submit\" value=\"{$lang->moderation[\'split_thread\']}\">\r\n                                <i class=\"fas fa-arrows-split-up-and-left me-2\"></i>\r\n                                {$lang->moderation[\'split_thread\']}\r\n                            </button>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <!-- Progress bar (hidden by default) -->\r\n                    <div class=\"progress mt-4\" style=\"height: 6px; display: none;\" id=\"progressBar\">\r\n                        <div class=\"progress-bar progress-bar-split progress-bar-striped progress-bar-animated\" \r\n                             role=\"progressbar\" style=\"width: 0%\"></div>\r\n                    </div>\r\n                </div>\r\n            </form>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- JavaScript -->\r\n    <script>\r\n    // Функция для подсчета количества постов\r\n    function countPosts() {\r\n        const postsInput = document.querySelector(\'input[name=\"posts\"]\');\r\n        if (!postsInput) return 0;\r\n        \r\n        const postsValue = postsInput.value || \'\';\r\n        let count = 0;\r\n        \r\n        if (postsValue) {\r\n            // Пробуем разные форматы разделителей\r\n            if (postsValue.includes(\'|\')) {\r\n                count = postsValue.split(\'|\').filter(id => {\r\n                    const trimmed = id.trim();\r\n                    return trimmed !== \'\' && !isNaN(parseInt(trimmed));\r\n                }).length;\r\n            } else if (postsValue.includes(\',\')) {\r\n                count = postsValue.split(\',\').filter(id => {\r\n                    const trimmed = id.trim();\r\n                    return trimmed !== \'\' && !isNaN(parseInt(trimmed));\r\n                }).length;\r\n            } else if (postsValue.includes(\'_\')) {\r\n                count = postsValue.split(\'_\').filter(id => {\r\n                    const trimmed = id.trim();\r\n                    return trimmed !== \'\' && !isNaN(parseInt(trimmed));\r\n                }).length;\r\n            } else if (postsValue.trim() !== \'\') {\r\n                const num = parseInt(postsValue.trim());\r\n                count = !isNaN(num) && num > 0 ? 1 : 0;\r\n            }\r\n        }\r\n        \r\n        return count;\r\n    }\r\n    \r\n    // Инициализация при загрузке\r\n    document.addEventListener(\'DOMContentLoaded\', function() {\r\n        // Подсчет постов\r\n        const postCount = countPosts();\r\n        document.querySelectorAll(\'#postsCount, #postsCount2\').forEach(el => {\r\n            if (el) el.textContent = postCount;\r\n        });\r\n        \r\n        // Стилизация select\r\n        const forumSelect = document.querySelector(\'select\');\r\n        if (forumSelect) {\r\n            forumSelect.classList.add(\'form-select-custom\', \'form-select\');\r\n        }\r\n        \r\n        // Стилизация input\r\n        const subjectInput = document.querySelector(\'input[name=\"newsubject\"]\');\r\n        if (subjectInput) {\r\n            subjectInput.classList.add(\'form-control-custom\');\r\n        }\r\n        \r\n        // Обработка формы\r\n        const form = document.getElementById(\'splitThreadForm\');\r\n        if (form) {\r\n            form.addEventListener(\'submit\', async function(e) {\r\n                e.preventDefault();\r\n                \r\n                const subjectInput = this.querySelector(\'input[name=\"newsubject\"]\');\r\n                const forumSelect = this.querySelector(\'select\');\r\n                const postCount = document.getElementById(\'postsCount\')?.textContent || \'0\';\r\n                \r\n                // Валидация заголовка\r\n                if (!subjectInput?.value.trim()) {\r\n                    if (typeof Swal !== \'undefined\') {\r\n                        await Swal.fire({\r\n                            icon: \'error\',\r\n                            title: \'Title Required\',\r\n                            text: \'Please enter a title for the new thread.\',\r\n                            confirmButtonColor: \'#0d6efd\'\r\n                        });\r\n                    } else {\r\n                        alert(\'Please enter a title for the new thread.\');\r\n                    }\r\n                    subjectInput?.focus();\r\n                    return false;\r\n                }\r\n                \r\n                // Валидация форума\r\n                if (!forumSelect?.value) {\r\n                    if (typeof Swal !== \'undefined\') {\r\n                        await Swal.fire({\r\n                            icon: \'error\',\r\n                            title: \'Forum Required\',\r\n                            text: \'Please select a destination forum.\',\r\n                            confirmButtonColor: \'#0d6efd\'\r\n                        });\r\n                    } else {\r\n                        alert(\'Please select a destination forum.\');\r\n                    }\r\n                    forumSelect?.focus();\r\n                    return false;\r\n                }\r\n                \r\n                const forumName = forumSelect.options[forumSelect.selectedIndex].text;\r\n                const newTitle = subjectInput.value;\r\n                \r\n                // Подтверждение\r\n                if (typeof Swal !== \'undefined\') {\r\n                    const result = await Swal.fire({\r\n                        title: \'<strong>Split Thread Confirmation</strong>\',\r\n                        html: `\r\n                            <div class=\"text-start\">\r\n                                <div class=\"alert alert-info border-0 mb-3\">\r\n                                    <i class=\"fas fa-info-circle me-2 text-primary\"></i>\r\n                                    You are about to create a new thread from <strong class=\"text-primary\">${postCount}</strong> selected post(s)\r\n                                </div>\r\n                                \r\n                                <div class=\"card border-primary mb-3\">\r\n                                    <div class=\"card-header bg-primary bg-opacity-10 text-primary py-2\">\r\n                                        <i class=\"fas fa-heading me-2\"></i><strong>New Thread Title:</strong>\r\n                                    </div>\r\n                                    <div class=\"card-body py-3\">\r\n                                        <h6 class=\"mb-1\">${newTitle}</h6>\r\n                                    </div>\r\n                                </div>\r\n                                \r\n                                <div class=\"card border-success mb-3\">\r\n                                    <div class=\"card-header bg-success bg-opacity-10 text-success py-2\">\r\n                                        <i class=\"fas fa-folder me-2\"></i><strong>Destination Forum:</strong>\r\n                                    </div>\r\n                                    <div class=\"card-body py-3\">\r\n                                        <h6 class=\"mb-1\">${forumName}</h6>\r\n                                    </div>\r\n                                </div>\r\n                                \r\n                                <div class=\"alert alert-warning\">\r\n                                    <h6 class=\"mb-2\"><i class=\"fas fa-exchange-alt me-2\"></i>What will happen:</h6>\r\n                                    <ul class=\"mb-0 ps-3\">\r\n                                        <li>${postCount} post(s) will be moved to the new thread</li>\r\n                                        <li>Original thread will retain remaining posts</li>\r\n                                        <li>A new thread will be created with the specified title</li>\r\n                                    </ul>\r\n                                </div>\r\n                            </div>\r\n                        `,\r\n                        icon: \'question\',\r\n                        showCancelButton: true,\r\n                        confirmButtonColor: \'#0d6efd\',\r\n                        cancelButtonColor: \'#6c757d\',\r\n                        confirmButtonText: `\r\n                            <i class=\"fas fa-arrows-split-up-and-left me-2\"></i>\r\n                            Split Thread\r\n                        `,\r\n                        cancelButtonText: `\r\n                            <i class=\"fas fa-times me-2\"></i>\r\n                            Cancel\r\n                        `,\r\n                        reverseButtons: true,\r\n                        width: 600\r\n                    });\r\n                    \r\n                    if (!result.isConfirmed) {\r\n                        return false;\r\n                    }\r\n                } else {\r\n                    const confirmMessage = `Create new thread \"${newTitle}\" in \"${forumName}\" with ${postCount} post(s)?`;\r\n                    if (!confirm(confirmMessage)) {\r\n                        return false;\r\n                    }\r\n                }\r\n                \r\n                // Показываем прогресс-бар\r\n                const progressBar = document.getElementById(\'progressBar\');\r\n                if (progressBar) {\r\n                    progressBar.style.display = \'block\';\r\n                    const progressBarInner = progressBar.querySelector(\'.progress-bar\');\r\n                    \r\n                    let width = 0;\r\n                    const interval = setInterval(() => {\r\n                        if (width >= 100) {\r\n                            clearInterval(interval);\r\n                        } else {\r\n                            width += 10;\r\n                            progressBarInner.style.width = width + \'%\';\r\n                        }\r\n                    }, 50);\r\n                }\r\n                \r\n                // Блокируем кнопку\r\n                const submitBtn = this.querySelector(\'button[type=\"submit\"]\');\r\n                if (submitBtn) {\r\n                    submitBtn.disabled = true;\r\n                    submitBtn.innerHTML = \'<i class=\"fas fa-spinner fa-spin me-2\"></i> Splitting...\';\r\n                }\r\n                \r\n                // Отправляем форму\r\n                setTimeout(() => {\r\n                    HTMLFormElement.prototype.submit.call(form);\r\n                }, 100);\r\n                \r\n                return false;\r\n            });\r\n        }\r\n    });\r\n    </script>\r\n</body>\r\n</html>\r\n','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1314','moderation_merge','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->merge_threads}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"legend mb-4\">{$lang->merge_threads}</div>\r\n<div class=\"ps-3 pe-3\">{$loginbox}</div>\r\n	<div class=\"ps-3 pe-3 mt-3\">\r\n{$lang->new_subject}\r\n<input type=\"text\" class=\"form-control border form-control-sm mb-3\" name=\"subject\" value=\"{$thread[\'subject\']}\" size=\"40\" /></td>\r\n\r\n{$lang->thread_to_merge_with}<br /><span class=\"text-muted\">{$lang->merge_with_note}</span>\r\n<input type=\"text\" class=\"form-control border form-control-sm mb-3\" name=\"threadurl\" size=\"40\" />\r\n\r\n<div class=\"text-end\"><input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->merge_threads}\" /></div>\r\n<input type=\"hidden\" name=\"action\" value=\"do_merge\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n	</div></div>\r\n	</div></div>\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1315','moderation_mergeposts_post','<div class=\"mt-4 mb-4 border border-5 p-3 rounded\">\r\n{$lang->posted_by} {$post[\'username\']} <span class=\"text-muted\">{$postdate}</span> <input type=\"checkbox\" class=\"form-check-input\" checked=\"checked\" name=\"mergepost[{$post[\'pid\']}]\" value=\"1\" />\r\n	<br /><br />\r\n\r\n{$message}\r\n</div>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1316','moderation_move','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->move_copy_thread}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"legend mb-4\">{$lang->move_copy_thread}</div>\r\n<div class=\"ps-3 pe-3 mb-3\">{$loginbox}</div>\r\n<div class=\"ps-3 pe-3\">{$lang->new_forum}\r\n{$forumselect}\r\n	<div class=\"mt-3\"></div>\r\n{$lang->method}<br />\r\n\r\n<label><input type=\"radio\" class=\"form-check-input\" name=\"method\" value=\"move\" /> {$lang->method_move}</label><br />\r\n<label><input type=\"radio\" class=\"form-check-input\" name=\"method\" value=\"redirect\" checked=\"checked\" /> {$lang->method_move_redirect}</label> <input type=\"text\" class=\"form-control border form-control-sm mt-2 mb-1\" name=\"redirect_expire\" size=\"3\" /> {$lang->redirect_expire_note}<br />\r\n<label><input type=\"radio\" class=\"form-check-input\" name=\"method\" value=\"copy\" /> {$lang->method_copy}</label><br />\r\n\r\n<div class=\"text-end mt-3\"><input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->move_copy_thread}\" /></div>\r\n<input type=\"hidden\" name=\"action\" value=\"do_move\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n</form>\r\n	</div></div>\r\n	</div></div>\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1317','moderation_purgespammer','<html>\r\n<head>\r\n<title>{$lang->purgespammer}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form method=\"post\" action=\"moderation.php\">\r\n<input type=\"hidden\" name=\"action\" value=\"do_purgespammer\" />\r\n<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"legend mb-4\">{$purgespammer_purge}</div>\r\n	<div class=\"ps-3 pe-3 text-muted\">{$purgespammer_purge_desc}</div>\r\n\r\n	<div class=\"ps-e pe-3 text-end mt-3\"><input class=\"btn btn-primary\" type=\"submit\" value=\"{$lang->purgespammer_submit}\" /></div>\r\n\r\n<input type=\"hidden\" name=\"uid\" value=\"{$uid}\" />\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n</form>\r\n	</div></div>\r\n	</div>\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1318','moderation_split','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->split_thread}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"legend mb-4\">{$lang->split_thread}</div>\r\n\r\n<div class=\"ps-3 pe-3\">{$loginbox}</div>\r\n\r\n<div class=\"ps-3 pe-3 mt-3\">{$lang->new_subject}\r\n<input type=\"text\" class=\"form-control border form-control-sm mb-3\" name=\"newsubject\" value=\"{$lang->split_thread_subject} {$thread[\'subject\']}\" size=\"50\" />\r\n\r\n{$lang->new_forum}\r\n{$forumselect}\r\n	</div>\r\n	<div class=\"legend mt-4 mb-4\">{$lang->posts_to_split}</div>\r\n<div class=\"ps-3 pe-3\">\r\n{$posts}\r\n\r\n<div class=\"mt-3 text-end\"><input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->split_thread}\" /></div>\r\n<input type=\"hidden\" name=\"action\" value=\"do_split\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n	</div></div>\r\n	</div></div>\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1319','moderation_split_post','<div class=\"mt-4 mb-4 border border-5 p-3 rounded\">\r\n{$lang->posted_by} {$post[\'username\']} <span class=\"text-muted\">{$postdate}</span> <input type=\"checkbox\" class=\"form-check-input\" name=\"splitpost[{$post[\'pid\']}]\" value=\"1\" />\r\n	<br /><br />\r\n\r\n{$message}\r\n</div>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1320','moderation_threadnotes','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->thread_notes_editor}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"legend mb-4\">{$lang->thread_notes_editor}</div>\r\n<div class=\"ps-3 pe-3 mb-4\">{$loginbox}</div>\r\n	\r\n	<div class=\"ps-3 pe-3\">\r\n	<span class=\"text-muted\">{$lang->below_notes}</span>\r\n<textarea name=\"threadnotes\" class=\"form-control border form-control-sm\" cols=\"80\" rows=\"10\" tabindex=\"1\">{$thread[\'notes\']}</textarea>\r\n\r\n<div class=\"mt-1 text-end\"><input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->update_notes}\" tabindex=\"2\" /></div>\r\n<input type=\"hidden\" name=\"action\" value=\"do_threadnotes\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n	</div>\r\n</form>\r\n	<div class=\"legend mt-4 mb-4\">{$lang->mod_logs}</div>\r\n	\r\n<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n	<div class=\"row pt-3 pb-3 m-0\">\r\n		<div class=\"col align-self-center\">\r\n			{$lang->mod_username}\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n			{$lang->mod_date}\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n			{$lang->mod_actions}\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n			{$lang->mod_information}\r\n		</div>\r\n	</div>\r\n	</div>\r\n\r\n{$modactions}\r\n\r\n	<div class=\"legend mt-4 mb-4\">{$lang->delayed_mod_queue}</div>\r\n	\r\n	<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n	<div class=\"row p-3\">\r\n		<div class=\"col align-self-center\">\r\n			{$lang->mod_username}\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n			{$lang->time_to_perform_action}\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n			{$lang->mod_actions}\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n			{$lang->mod_information}\r\n		</div>\r\n	</div>\r\n	</div>\r\n\r\n{$delayedmods}\r\n\r\n	</div></div></div>\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1321','moderation_threadnotes_delayedmodaction','<div class=\"row pt-3 pb-3 m-0 border-bottom\">\r\n		<div class=\"col-6 col-sm-6 col-md-6 col-lg col-xl col-xxl align-self-center\">\r\n			{$delayedmod[\'profilelink\']}\r\n		</div>\r\n		<div class=\"col-6 col-sm-6 col-md-6 col-lg col-xl col-xxl align-self-center text-muted\">\r\n			{$delayedmod[\'dateline\']}\r\n		</div>\r\n		<div class=\"col-6 col-sm-6 col-md-6 col-lg col-xl col-xxl align-self-center\">\r\n			{$delayedmod[\'action\']}\r\n		</div>\r\n		<div class=\"col-6 col-sm-6 col-md-6 col-lg col-xl col-xxl align-self-center\">\r\n			{$info}\r\n		</div>\r\n	</div>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1322','moderation_threadnotes_modaction','<div class=\"row pt-3 pb-3 m-0 border-bottom\">\r\n		<div class=\"col-6 col-sm-6 col-md-6 col-lg col-xl col-xxl align-self-center\">\r\n			{$modaction[\'profilelink\']}\r\n		</div>\r\n		<div class=\"col-6 col-sm-6 col-md-6 col-lg col-xl col-xxl align-self-center text-muted\">\r\n			{$modaction[\'dateline\']}\r\n		</div>\r\n		<div class=\"col-6 col-sm-6 col-md-6 col-lg col-xl col-xxl align-self-center\">\r\n			{$modaction[\'action\']}\r\n		</div>\r\n		<div class=\"col-6 col-sm-6 col-md-6 col-lg col-xl col-xxl align-self-center\">\r\n			{$info}\r\n		</div>\r\n	</div>','2','1830','','1720609281');
