INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1326','multipage_breadcrumb','<div id=\"breadcrumb_multipage_popup\" style=\"display: none;\">\r\n{$prevpage}{$start}{$mppage}{$end}{$nextpage}\r\n</div>\r\n<script type=\"text/javascript\">\r\n// <!--\r\n	if(use_xmlhttprequest == \"1\")\r\n	{\r\n		$(\"#breadcrumb_multipage\").popupMenu();\r\n	}\r\n// -->\r\n</script>','2','1837','','1720609281');
