INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1366','polls_showresults','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->polls[\'poll_results\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n	<div class=\"container-md\">\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n		{$lang->poll} {$poll[\'question\']}\r\n	</div>\r\n	<div class=\"card-body\">\r\n\r\n{$polloptions}\r\n					\r\n	</div>\r\n	<div class=\"card-footer text-center\">\r\n	{$lang->polls[\'poll_total\']} {$poll[\'numvotes\']} {$lang->polls[\'poll_votes\']} {$totpercent}\r\n						</div>\r\n					</div>\r\n\r\n	</div>\r\n	\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1367','polls_showresults_resultbit','<div class=\"row pt-3 border-top text-forum\">\r\n<div class=\"col-auto text-forum\">\r\n	{$option}{$votestar}\r\n</div>\r\n	<div class=\"col-lg text-end align-self-center\">\r\n		{$votes} ({$percent}%)\r\n	</div>\r\n</div>\r\n<div class=\"row pb-3 text-forum\">\r\n	\r\n	\r\n	<div class=\"col-lg\">\r\n	<div class=\"progress mb-1\" style=\"height: 25px\">\r\n  <div class=\"progress-bar pg-primary\" role=\"progressbar\" style=\"width:{$percent}%\"  aria-valuenow=\"{$percent}\" aria-valuemin=\"0\" aria-valuemax=\"100\"></div>\r\n</div>\r\n		<div class=\"mt-1\">{$userlist}</div>\r\n</div>	\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1383','postbit','<!-- begin new layout -->\r\n	\r\n{$ignore_bit}{$deleted_bit}\r\n<a name=\"pid{$post[\'pid\']}\" id=\"pid{$post[\'pid\']}\"></a>\r\n<div class=\"row g-2 mb-4\" style=\"{$post_visibility}\" id=\"post_{$post[\'pid\']}\">\r\n<div class=\"col-auto d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">{$post[\'useravatar\']}</div>\r\n<div class=\"col\">\r\n<div class=\"card\">\r\n<div class=\"card-body inline_row {$unapproved_shade}\">\r\n				\r\n<div class=\"row m-0 p-0 mb-3 mb-sm-3 mb-md-3 mb-lg-0 mb-xl-0 mb-xxl-0\">\r\n<div class=\"col-auto d-block d-sm-block d-md-block d-lg-none d-xl-none d-xxl-none m-0 p-0 me-2 me-sm-2 me-md-2 me-lg-0 me-xl-0 me-xxl-0 align-self-center\">\r\n{$post[\'useravatar\']}\r\n</div>\r\n<div class=\"col m-0 p-0 align-self-center\">\r\n<h6 class=\"card-title mb-0 mb-sm-0 mb-md-0 mb-lg-3 mb-xl-3 mb-xxl-3\"><span style=\"font-weight: 700\">{$post[\'profilelink\']}</span> {$post[\'onlinestatus\']} &nbsp;&nbsp;<span class=\"text-uppercase text-desc small fw-normal\">{$post[\'postdate\']}</span></span></h6>\r\n</div>\r\n<div class=\"col-auto m-0 p-0 align-self-center text-end text-14\">\r\n{$post[\'posturl\']}\r\n</div>\r\n</div>\r\n				\r\n<div  class=\"post_body scaleimages\" id=\"pid_{$post[\'pid\']}\">\r\n{$post[\'message\']}\r\n{$post[\'attachments\']}	\r\n</div>\r\n\r\n\r\n<span class=\"post_edit\" id=\"edited_by_{$post[\'pid\']}\">{$post[\'editedmsg\']}</span>			\r\n{$post[\'signature\']}\r\n{$post[\'poststatus\']}	{$post[\'input_editreason\']}{$post[\'iplogged\']}			\r\n</div>\r\n<div class=\"card-footer border-top-0 py-2 my-0\">\r\n			\r\n			<!-- hidden -->\r\n<div class=\"row mt-0 pt-0 mb-0 pb-0\">\r\n<div class=\"col-auto align-self-center small text-start pe-0 me-0\">\r\n{$post[\'button_multiquote\']}</div>	\r\n\r\n<div class=\"col-auto align-self-center small text-start pe-0 me-0\">\r\n{$post[\'button_rep\']}</div>	\