INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1466','private_search_messagebit','<div class=\"card mb-0 border-0\">\r\n	<div class=\"card-body pt-0 inline_row\">\r\n	<div class=\"row g-2 pb-3 border-bottom mb-0\">\r\n		<div class=\"col-auto col-sm-auto col-md-auto col-lg-1 col-xl-1 col-xxl-1 align-self-center\">\r\n			<avatarep_uid_[{$tofromuid}]>\r\n				</div>\r\n			<div class=\"col align-self-center\">\r\n				<h6 class=\"mb-0 text-forum\"><a class=\"{$msgstatus}\" href=\"private.php?action=read&amp;pmid={$message[\'pmid\']}\">{$message[\'subject\']}</a>{$denyreceipt}</h6>\r\n				<i class=\"fa-regular fa-folder-open small text-desc\"></i> &nbsp;<a href=\"private.php?fid={$message[\'folder\']}\" class=\"links small\">{$foldername}</a> &mdash; <span class=\"links small\">{$tofromusername}</span>\r\n			</div>\r\n			<div class=\"col-auto d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block align-self-center\">\r\n				{$icon} <img src=\"{$theme[\'imgdir\']}/{$msgstatus}.png\" alt=\"{$msgalt}\" title=\"{$msgalt}\" /> \r\n			</div>\r\n			<div class=\"col-lg-3 text-muted align-self-center\">\r\n				{$senddate}\r\n				<span class=\"float-end\">\r\n					<input type=\"checkbox\" class=\"form-check-input\" name=\"check[{$message[\'pmid\']}]\" value=\"1\" />\r\n				</span>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1467','private_search_results','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->private[\'private_messaging\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n	<form action=\"private.php\" method=\"post\" name=\"pmForm\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n	\r\n<div class=\"card border-0 mb-3\">\r\n<div class=\"card-header py-3 bg-nav rounded border-bottom-0\">\r\n		\r\n		<div class=\"row g-2 text-forum\">\r\n			<div class=\"col-1\">\r\n				&nbsp;\r\n			</div>\r\n			<div class=\"col align-self-center\">\r\n				{$lang->private[\'message\']}</a> &mdash; {$lang->private[\'sender\']}\r\n			</div>\r\n			<div class=\"col-3 align-self-center\">\r\n				<span class=\"d-none d-sm-none d-md-none d-lg-inline-block d-xl-inline-block d-xxl-inline-block\">{$lang->private[\'date_sent\']}</span>\r\n				<span class=\"float-end\"><input name=\"allbox\" title=\"{$lang->private[\'check_all\']}\" type=\"checkbox\" class=\"form-check-input checkall\" value=\"{$lang->private[\'check_all\']}\" /></span>\r\n			</div>\r\n	</div>\r\n	\r\n	</div>\r\n	</div>	\r\n	\r\n{$messagelist}\r\n	\r\n	\r\n	\r\n	\r\n	\r\n	\r\n	\r\n	<div class=\"card border-0 mt-3\">\r\n<div class=\"card-header py-3 bg-nav rounded border-bottom-0\">\r\n		\r\n		<div class=\"row g-1\">\r\n			<div class=\"col\">\r\n				&nbsp;\r\n			</div>\r\n						<div class=\"col-auto\">\r\n				<input type=\"submit\" class=\"btn btn-primary btn-sm\" name=\"moveto\" value=\"{$lang->private[\'move_to\']}\" />&nbsp; <i class=\"fa-solid fa-arrow-right\"></i>&nbsp;  \r\n			</div>\r\n			<div class=\"col-auto\">\r\n	{$folderoplist} \r\n			</div>\r\n			<div class=\"col-auto\">\r\n				&nbsp;{$lang->private[\'or\']}&nbsp; <input type=\"submit\" class=\"btn btn-primary btn-sm\" name=\"delete\" value=\"{$lang->private[\'delete\']}\" />\r\n			</div>\r\n			<div class=\"col\">\r\n				&nbsp;\r\n			</div>\r\n	</div>\r\n		</div>\r\n	</div>	\r\n\r\n<input type=\"hidden\" name=\"action\" value=\"do_stuff\" />\r\n</form>\r\n\r\n{$multipage}\r\n</div></div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1468','private_send','<html>\r\n<head>\r\n<title>{$lang->private[\'compose_pm\']}</title>\r\n\r\n    <style type=\"text/css\">\r\n        \r\n.noicon {\r\n    background: #f7f7f7;\r\n    padding: 5px;\r\n    border-radius: 4px;\r\n    cursor: pointer;\r\n    margin-bottom: 1px;\r\n}\r\n        \r\n.noicon:active, .noicon:focus, .noicon:visited {\r\n    background: #dedede;\r\n    padding: 5px;\r\n    border-radius: 4px;\r\n    cursor: pointer;\r\n    margin-bottom: 1px;\r\n}\r\n        \r\n\r\n[type=radio] { \r\n  position: absolute;\r\n  opacity: 0;\r\n  width: 0;\r\n  height: 0;\r\n}\r\n\r\n\r\n[type=radio] + img {\r\n  cursor: pointer;\r\n    background: #f7f7f7;\r\n    padding: 7px;\r\n    border-radius: 4px;\r\n}\r\n\r\n\r\n[type=radio]:checked + img {\r\n    background: #dedede;\r\n}\r\n\r\n/* Стили для тегов Select2 */\r\n.select2-tags-container {\r\n    position: relative;\r\n    border: 1px solid #ddd;\r\n    border-radius: 4px;\r\n    padding: 6px;\r\n    min-height: 42px;\r\n    cursor: text;\r\n    background-color: white;\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    align-items: center;\r\n    gap: 6px;\r\n    transition: border-color 0.3s ease, box-shadow 0.3s ease;\r\n}\r\n\r\n.select2-tags-container.focused {\r\n    border-color: #007bff;\r\n    box-shadow: 0 0 0 2px rgba(0, 123, 255, 0.25);\r\n}\r\n\r\n.select2-tags-container.limit-reached {\r\n    border-color: #dc3545;\r\n    box-shadow: 0 0 0 2px rgba(220, 53, 69, 0.25);\r\n    background-color: #fff5f5;\r\n}\r\n\r\n.select2-tag {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    background-color: #e9ecef;\r\n    border-radius: 16px;\r\n    padding: 4px 8px;\r\n    font-size: 14px;\r\n    color: #495057;\r\n    animation: select2FadeIn 0.3s ease;\r\n}\r\n\r\n@keyframes select2FadeIn {\r\n    from { opacity: 0; transform: scale(0.8); }\r\n    to { opacity: 1; transform: scale(1); }\r\n}\r\n\r\n.select2-tag-text {\r\n    margin-right: 4px;\r\n}\r\n\r\n.select2-tag-remove {\r\n    cursor: pointer;\r\n    color: #6c757d;\r\n    font-weight: bold;\r\n    font-size: 16px;\r\n    line-height: 1;\r\n    padding: 0;\r\n    background: none;\r\n    border: none;\r\n    width: 16px;\r\n    height: 16px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n}\r\n\r\n.select2-tag-remove:hover {\r\n    color: #dc3545;\r\n}\r\n\r\n.select2-tags-input {\r\n    border: none;\r\n    outline: none;\r\n    padding: 6px 0;\r\n    flex-grow: 1;\r\n    min-width: 120px;\r\n    font-size: 14px;\r\n    background: transparent;\r\n}\r\n\r\n.select2-tags-input::placeholder {\r\n    color: #6c757d;\r\n}\r\n\r\n.select2-tags-input:disabled {\r\n    background-color: #e9ecef;\r\n    opacity: 0.6;\r\n    cursor: not-allowed;\r\n}\r\n\r\n.select2-dropdown {\r\n    background: white;\r\n    border: 1px solid #ddd;\r\n    border-radius: 4px;\r\n    max-height: 200px;\r\n    overflow-y: auto;\r\n    z-index: 1000;\r\n    box-shadow: 0 2px 8px rgba(0,0,0,0.1);\r\n    display: none;\r\n}\r\n\r\n.select2-item {\r\n    padding: 8px 12px;\r\n    cursor: pointer;\r\n    border-bottom: 1px solid #f0f0f0;\r\n    transition: background-color 0.15s ease;\r\n    font-size: 14px;\r\n}\r\n\r\n.select2-item:last-child {\r\n    border-bottom: none;\r\n}\r\n\r\n.select2-item:hover, .select2-item.active {\r\n    background-color: #007bff;\r\n    color: white;\r\n}\r\n\r\n.select2-message {\r\n    padding: 8px 12px;\r\n    color: #6c757d;\r\n    font-style: italic;\r\n    font-size: 14px;\r\n}\r\n\r\n/* Стили для счетчика и ошибок */\r\n.select2-counter {\r\n    font-size: 12px;\r\n    color: #6c757d;\r\n    margin-top: 4px;\r\n    font-weight: normal;\r\n}\r\n\r\n.select2-counter.near-limit {\r\n    color: #ffc107;\r\n    font-weight: bold;\r\n}\r\n\r\n.select2-counter.limit-reached {\r\n    color: #dc3545;\r\n    font-weight: bold;\r\n}\r\n\r\n.select2-error {\r\n    color: #dc3545;\r\n    font-size: 12px;\r\n    margin-top: 4px;\r\n    padding: 4px 8px;\r\n    background-color: #f8d7da;\r\n    border: 1px solid #f5c6cb;\r\n    border-radius: 4px;\r\n    display: none;\r\n}\r\n\r\n.select2-error.show {\r\n    display: block;\r\n    animation: fadeIn 0.3s ease;\r\n}\r\n\r\n@keyframes fadeIn {\r\n    from { opacity: 0; transform: translateY(-5px); }\r\n    to { opacity: 1; transform: translateY(0); }\r\n}\r\n\r\n\r\n</style>    \r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/usercp.js?ver=1827\"></script>\r\n</head>\r\n<body>\r\n\r\n<form action=\"private.php\" method=\"post\" name=\"input\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n\r\n<div id=\"fileIdsContainer\"></div>\r\n\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n                \r\n</div>\r\n<div class=\"col\">\r\n    \r\n{$preview}\r\n{$send_errors}                \r\n\r\n\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n    \r\n    \r\n    <div class=\"mb-3 p-0 pb-4 border-bottom\">\r\n        <input name=\"to\" id=\"to\" value=\"{$to}\" tabindex=\"1\" class=\"form-control border\" placeholder=\"Search for users\" style=\"display: none;\">\r\n        <div id=\"to-container\"></div>\r\n        <!-- Счетчик получателей -->\r\n        <div class=\"select2-counter\" id=\"recipientCounter\">Recipients: 0/5</div>\r\n        <!-- Сообщение об ошибке -->\r\n        <div class=\"select2-error\" id=\"recipientError\">You are only allowed to send messages to 5 users at a time</div>\r\n    <span style=\"font-size: 12px\" class=\"text-muted\">Click to search and select users</span>\r\n    </div>\r\n\r\n<div class=\"mb-3 p-0 pb-4 border-bottom\">\r\n    <input type=\"text\" class=\"form-control border\" name=\"subject\" maxlength=\"85\" value=\"{$subject}\" tabindex=\"3\" placeholder=\"Subject\" />\r\n    </div>\r\n    \r\n    {$codebuttons}\r\n\r\n\r\n<textarea name=\"message\" id=\"message\" class=\"form-control form-control-sm border\" style=\"width: 100%; height: 400px\" tabindex=\"4\">{$message}</textarea>\r\n\r\n\r\n<div class=\"mt-2\"><a class=\"links\" data-bs-toggle=\"collapse\" aria-expanded=\"false\" aria-controls=\"collapse-1\" href=\"#collapse-pmop\" role=\"button\"><i class=\"fa-solid fa-gear\"></i> &nbsp;Options</a> &nbsp;&nbsp;&nbsp; <button type=\"submit\" class=\"btn-thread\" name=\"preview\" value=\"Preview\" tabindex=\"11\"><i class=\"fa-solid fa-pencil\"></i> &nbsp;Preview</button></div>\r\n\r\n<div id=\"collapse-pmop\" class=\"collapse\">\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">Options</div>\r\n<div class=\"row g-3 m-auto pb-0 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\nOptions\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"checkbox\" class=\"form-check-input\" name=\"options[savecopy]\" value=\"1\" tabindex=\"7\" {$optionschecked[\'savecopy\']} /> Save a copy in my Sent Items folder <br />\r\n{$private_send_tracking}\r\n</div>\r\n</div>\r\n</div>\r\n    \r\n    \r\n\r\n<input type=\"hidden\" name=\"action\" value=\"do_send\" />\r\n<input type=\"hidden\" name=\"pmid\" value=\"{$pmid}\" />\r\n<input type=\"hidden\" name=\"do\" value=\"{$do}\" />\r\n    </div>\r\n<div class=\"card-footer text-center\">\r\n\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"Send Message\" tabindex=\"9\" accesskey=\"s\"><i class=\"fa-solid fa-envelope\"></i> &nbsp;Send Message</button>\r\n\r\n</div>\r\n    \r\n</form>\r\n</div></div>\r\n</div></div>\r\n</div>\r\n\r\n<script type=\"text/javascript\">\r\n// Глобальная переменная для доступа к полю из тестовых функций\r\nvar globalSelect2Field = null;\r\n\r\n// Класс для управления полем с тегами\r\nfunction Select2Field(inputId, type, maxRecipients, texts) {\r\n    this.originalInput = document.getElementById(inputId);\r\n    if (!this.originalInput) {\r\n        console.error(\'Element not found:\', inputId);\r\n        return;\r\n    }\r\n    \r\n    // Создаем контейнер для тегов\r\n    this.container = document.createElement(\'div\');\r\n    this.container.className = \'select2-tags-container\';\r\n    this.container.id = inputId + \'-container\';\r\n    \r\n    // Создаем поле ввода внутри контейнера\r\n    this.input = document.createElement(\'input\');\r\n    this.input.type = \'text\';\r\n    this.input.className = \'select2-tags-input\';\r\n    this.input.placeholder = texts.searchUser;\r\n    this.container.appendChild(this.input);\r\n    \r\n    // Заменяем оригинальный input на наш контейнер\r\n    this.originalInput.parentNode.insertBefore(this.container, this.originalInput.nextSibling);\r\n    this.originalInput.style.display = \'none\';\r\n    \r\n    this.type = type;\r\n    this.maxRecipients = maxRecipients;\r\n    this.texts = texts;\r\n    this.recipients = [];\r\n    this.debounceTimer = null;\r\n    this.onChange = null;\r\n    this.clickHandler = null;\r\n    \r\n    // Получаем элементы счетчика и ошибки\r\n    this.counterElement = document.getElementById(\'recipientCounter\');\r\n    this.errorElement = document.getElementById(\'recipientError\');\r\n    this.testCounterElement = document.getElementById(\'recipientCount\');\r\n    this.testLimitElement = document.getElementById(\'recipientLimit\');\r\n    this.testErrorElement = document.getElementById(\'testError\');\r\n    \r\n    // Создаем dropdown\r\n    this.dropdown = document.createElement(\'div\');\r\n    this.dropdown.className = \'select2-dropdown\';\r\n    document.body.appendChild(this.dropdown);\r\n    \r\n    this.init();\r\n    this.initExistingValues();\r\n    this.updateCounter();\r\n}\r\n\r\nSelect2Field.prototype.init = function() {\r\n    var self = this;\r\n    \r\n    // Обработчик фокуса\r\n    this.input.addEventListener(\'focus\', function() {\r\n        self.container.classList.add(\'focused\');\r\n        self.updateDropdownPosition();\r\n        if (self.input.value.trim().length >= 2) {\r\n            self.searchUsers(self.input.value.trim());\r\n        }\r\n    });\r\n    \r\n    // Обработчик потери фокуса\r\n    this.input.addEventListener(\'blur\', function() {\r\n        setTimeout(function() {\r\n            self.container.classList.remove(\'focused\');\r\n            self.dropdown.style.display = \'none\';\r\n            \r\n            // Если в поле ввода есть текст, добавляем его как получателя\r\n            if (self.input.value.trim().length >= 2) {\r\n                self.addRecipient(self.input.value.trim());\r\n            }\r\n        }, 200);\r\n    });\r\n    \r\n    // Обработчик ввода\r\n    this.input.addEventListener(\'input\', function(e) {\r\n        var query = e.target.value.trim();\r\n        \r\n        clearTimeout(self.debounceTimer);\r\n        self.debounceTimer = setTimeout(function() {\r\n            if (query.length > 0 && query.length < 2) {\r\n                self.showMessage(self.texts.inputTooShort);\r\n                return;\r\n            }\r\n            \r\n            if (query.length >= 2) {\r\n                self.searchUsers(query);\r\n            } else {\r\n                self.dropdown.style.display = \'none\';\r\n            }\r\n        }, 300);\r\n    });\r\n    \r\n    // Обработчик нажатия клавиш\r\n    this.input.addEventListener(\'keydown\', function(e) {\r\n        var items = self.dropdown.querySelectorAll(\'.select2-item\');\r\n        var activeItem = self.dropdown.querySelector(\'.active\');\r\n        \r\n        switch(e.key) {\r\n            case \'ArrowDown\':\r\n                e.preventDefault();\r\n                self.navigateDropdown(items, activeItem, \'down\');\r\n                break;\r\n            case \'ArrowUp\':\r\n                e.preventDefault();\r\n                self.navigateDropdown(items, activeItem, \'up\');\r\n                break;\r\n            case \'Enter\':\r\n                if (activeItem) {\r\n                    e.preventDefault();\r\n                    var username = activeItem.getAttribute(\'data-username\');\r\n                    self.addRecipient(username);\r\n                } else if (self.input.value.trim().length >= 2) {\r\n                    e.preventDefault();\r\n                    self.addRecipient(self.input.value.trim());\r\n                }\r\n                break;\r\n            case \'Escape\':\r\n                self.dropdown.style.display = \'none\';\r\n                if (activeItem) {\r\n                    activeItem.classList.remove(\'active\');\r\n                }\r\n                break;\r\n            case \'Backspace\':\r\n                if (self.input.value === \'\' && self.recipients.length > 0) {\r\n                    e.preventDefault();\r\n                    self.removeRecipient(self.recipients[self.recipients.length - 1]);\r\n                }\r\n                break;\r\n            case \',\':\r\n            case \';\':\r\n                // Добавляем получателя при вводе запятой или точки с запятой\r\n                if (self.input.value.trim().length > 0) {\r\n                    e.preventDefault();\r\n                    var username = self.input.value.slice(0, -1).trim();\r\n                    if (username) {\r\n                        self.addRecipient(username);\r\n                    }\r\n                }\r\n                break;\r\n        }\r\n    });\r\n    \r\n    window.addEventListener(\'resize\', function() {\r\n        self.updateDropdownPosition();\r\n    });\r\n};\r\n\r\nSelect2Field.prototype.initExistingValues = function() {\r\n    if (this.originalInput.value) {\r\n        var values = this.originalInput.value.split(\',\')\r\n            .map(function(v) { return v.trim(); })\r\n            .filter(function(v) { return v !== \'\'; });\r\n        \r\n        var self = this;\r\n        values.forEach(function(value) {\r\n            self.addRecipient(value, true);\r\n        });\r\n    }\r\n};\r\n\r\nSelect2Field.prototype.updateCounter = function() {\r\n    var count = this.getRecipientsCount();\r\n    var limit = this.getMaxSelectionSize();\r\n    \r\n    // Обновляем основной счетчик\r\n    if (this.counterElement) {\r\n        this.counterElement.textContent = \'Recipients: \' + count + \'/\' + limit;\r\n        \r\n        // Добавляем классы в зависимости от количества\r\n        this.counterElement.classList.remove(\'near-limit\', \'limit-reached\');\r\n        if (count >= limit) {\r\n            this.counterElement.classList.add(\'limit-reached\');\r\n        } else if (count >= limit - 2) {\r\n            this.counterElement.classList.add(\'near-limit\');\r\n        }\r\n    }\r\n    \r\n    // Обновляем TEST COUNTER\r\n    if (this.testCounterElement) {\r\n        this.testCounterElement.textContent = count;\r\n    }\r\n    if (this.testLimitElement) {\r\n        this.testLimitElement.textContent = limit;\r\n    }\r\n    \r\n    // Проверяем лимит и обновляем UI\r\n    this.checkLimit();\r\n};\r\n\r\nSelect2Field.prototype.checkLimit = function() {\r\n    var count = this.getRecipientsCount();\r\n    var limit = this.getMaxSelectionSize();\r\n    \r\n    if (count >= limit) {\r\n        // Лимит достигнут - показываем ошибки и отключаем поле\r\n        this.container.classList.add(\'limit-reached\');\r\n        if (this.errorElement) {\r\n            this.errorElement.classList.add(\'show\');\r\n        }\r\n        if (this.testErrorElement) {\r\n            this.testErrorElement.style.display = \'block\';\r\n        }\r\n        this.disable();\r\n    } else {\r\n        // Лимит не достигнут - скрываем ошибки и включаем поле\r\n        this.container.classList.remove(\'limit-reached\');\r\n        if (this.errorElement) {\r\n            this.errorElement.classList.remove(\'show\');\r\n        }\r\n        if (this.testErrorElement) {\r\n            this.testErrorElement.style.display = \'none\';\r\n        }\r\n        this.enable();\r\n    }\r\n};\r\n\r\nSelect2Field.prototype.updateDropdownPosition = function() {\r\n    var rect = this.container.getBoundingClientRect();\r\n    this.dropdown.style.position = \'fixed\';\r\n    this.dropdown.style.top = (rect.bottom + window.scrollY) + \'px\';\r\n    this.dropdown.style.left = (rect.left + window.scrollX) + \'px\';\r\n    this.dropdown.style.width = rect.width + \'px\';\r\n};\r\n\r\nSelect2Field.prototype.navigateDropdown = function(items, activeItem, direction) {\r\n    if (items.length === 0) return;\r\n    \r\n    if (!activeItem) {\r\n        items[0].classList.add(\'active\');\r\n    } else {\r\n        var currentIndex = Array.from(items).indexOf(activeItem);\r\n        var nextIndex;\r\n        \r\n        if (direction === \'down\') {\r\n            nextIndex = (currentIndex + 1) % items.length;\r\n        } else {\r\n            nextIndex = currentIndex > 0 ? currentIndex - 1 : items.length - 1;\r\n        }\r\n        \r\n        activeItem.classList.remove(\'active\');\r\n        items[nextIndex].classList.add(\'active\');\r\n    }\r\n};\r\n\r\nSelect2Field.prototype.searchUsers = function(query) {\r\n    var self = this;\r\n    if (query.length < 2) {\r\n        this.dropdown.style.display = \'none\';\r\n        return;\r\n    }\r\n    \r\n    fetch(\"xmlhttp.php?action=get_users&query=\" + encodeURIComponent(query))\r\n        .then(function(response) {\r\n            if (!response.ok) {\r\n                throw new Error(\'Network response was not ok\');\r\n            }\r\n            return response.json();\r\n        })\r\n        .then(function(data) {\r\n            self.displayResults(data);\r\n        })\r\n        .catch(function(error) {\r\n            console.error(\'Error:\', error);\r\n            self.dropdown.style.display = \'none\';\r\n        });\r\n};\r\n\r\nSelect2Field.prototype.displayResults = function(users) {\r\n    this.dropdown.innerHTML = \'\';\r\n    \r\n    if (!users || users.length === 0) {\r\n        this.showMessage(this.texts.noMatches);\r\n        return;\r\n    }\r\n    \r\n    if (this.clickHandler) {\r\n        this.dropdown.removeEventListener(\'click\', this.clickHandler);\r\n    }\r\n    \r\n    var self = this;\r\n    users.forEach(function(user) {\r\n        var username = user.username || user.text || user.name || user.label || \"\";\r\n        var item = document.createElement(\'div\');\r\n        item.className = \'select2-item\';\r\n        item.textContent = username;\r\n        item.setAttribute(\'data-username\', username);\r\n        self.dropdown.appendChild(item);\r\n    });\r\n    \r\n    this.clickHandler = function(e) {\r\n        var item = e.target.closest(\'.select2-item\');\r\n        if (item) {\r\n            var username = item.getAttribute(\'data-username\');\r\n            self.addRecipient(username);\r\n            self.dropdown.style.display = \'none\';\r\n        }\r\n    };\r\n    \r\n    this.dropdown.addEventListener(\'click\', this.clickHandler);\r\n    this.dropdown.style.display = \'block\';\r\n    this.updateDropdownPosition();\r\n};\r\n\r\nSelect2Field.prototype.showMessage = function(message) {\r\n    this.dropdown.innerHTML = \'<div class=\"select2-message\">\' + message + \'</div>\';\r\n    this.dropdown.style.display = \'block\';\r\n    this.updateDropdownPosition();\r\n};\r\n\r\nSelect2Field.prototype.addRecipient = function(username, skipDuplicateCheck) {\r\n    if (this.getRecipientsCount() >= this.getMaxSelectionSize()) {\r\n        this.showMessage(this.texts.selectionTooBig);\r\n        return;\r\n    }\r\n    \r\n    if (!skipDuplicateCheck && this.recipients.includes(username)) {\r\n        return;\r\n    }\r\n    \r\n    if (!this.recipients.includes(username)) {\r\n        this.recipients.push(username);\r\n        \r\n        // Создаем тег (чип)\r\n        var tag = document.createElement(\'div\');\r\n        tag.className = \'select2-tag\';\r\n        tag.innerHTML = \r\n            \'<span class=\"select2-tag-text\">\' + username + \'</span>\' +\r\n            \'<button type=\"button\" class=\"select2-tag-remove\" data-username=\"\' + username + \'\">×</button>\';\r\n        \r\n        // Вставляем тег перед полем ввода\r\n        this.container.insertBefore(tag, this.input);\r\n        \r\n        // Добавляем обработчик удаления\r\n        var removeButton = tag.querySelector(\'.select2-tag-remove\');\r\n        var self = this;\r\n        removeButton.addEventListener(\'click\', function(e) {\r\n            e.preventDefault();\r\n            e.stopPropagation();\r\n            self.removeRecipient(username);\r\n        });\r\n        \r\n        // Очищаем поле ввода\r\n        this.input.value = \'\';\r\n        \r\n        // Обновляем оригинальное поле\r\n        this.updateOriginalInput();\r\n        \r\n        // Обновляем счетчик и проверяем лимит\r\n        this.updateCounter();\r\n        \r\n        if (this.onChange) this.onChange();\r\n    }\r\n    \r\n    this.dropdown.style.display = \'none\';\r\n};\r\n\r\nSelect2Field.prototype.removeRecipient = function(username) {\r\n    var index = this.recipients.indexOf(username);\r\n    if (index !== -1) {\r\n        this.recipients.splice(index, 1);\r\n        \r\n        // Удаляем соответствующий тег\r\n        var tags = this.container.querySelectorAll(\'.select2-tag\');\r\n        var self = this;\r\n        tags.forEach(function(tag) {\r\n            var tagUsername = tag.querySelector(\'.select2-tag-remove\').getAttribute(\'data-username\');\r\n            if (tagUsername === username) {\r\n                self.container.removeChild(tag);\r\n            }\r\n        });\r\n        \r\n        // Обновляем оригинальное поле\r\n        this.updateOriginalInput();\r\n        \r\n        // Обновляем счетчик и проверяем лимит\r\n        this.updateCounter();\r\n        \r\n        if (this.onChange) this.onChange();\r\n    }\r\n};\r\n\r\nSelect2Field.prototype.updateOriginalInput = function() {\r\n    if (this.recipients && this.recipients.length > 0) {\r\n        this.originalInput.value = this.recipients.join(\', \');\r\n    } else {\r\n        this.originalInput.value = \'\';\r\n    }\r\n    \r\n    var event = new Event(\'change\', { bubbles: true });\r\n    this.originalInput.dispatchEvent(event);\r\n};\r\n\r\nSelect2Field.prototype.getRecipientsCount = function() {\r\n    return this.recipients.length;\r\n};\r\n\r\nSelect2Field.prototype.getMaxSelectionSize = function() {\r\n    return this.maxRecipients;\r\n};\r\n\r\nSelect2Field.prototype.enable = function() {\r\n    this.input.disabled = false;\r\n    this.input.placeholder = this.texts.searchUser;\r\n};\r\n\r\nSelect2Field.prototype.disable = function() {\r\n    this.input.disabled = true;\r\n    this.input.placeholder = this.texts.selectionTooBig;\r\n};\r\n\r\nSelect2Field.prototype.forceUpdate = function() {\r\n    this.updateOriginalInput();\r\n};\r\n\r\n// Методы для тестирования\r\nSelect2Field.prototype.addTestUser = function(username) {\r\n    var testUsername = username || \'TestUser\' + (this.getRecipientsCount() + 1);\r\n    if (this.getRecipientsCount() < this.getMaxSelectionSize()) {\r\n        this.addRecipient(testUsername);\r\n    }\r\n};\r\n\r\nSelect2Field.prototype.removeTestUser = function() {\r\n    if (this.getRecipientsCount() > 0) {\r\n        this.removeRecipient(this.recipients[this.recipients.length - 1]);\r\n    }\r\n};\r\n\r\nSelect2Field.prototype.resetTest = function() {\r\n    var self = this;\r\n    this.recipients.forEach(function(recipient) {\r\n        self.removeRecipient(recipient);\r\n    });\r\n};\r\n\r\ndocument.addEventListener(\"DOMContentLoaded\", function() {\r\n    // Конфигурация\r\n    var maxRecipients = {$usergroups[\'maxpmrecipients\']}; // Лимит получателей\r\n    \r\n	var texts = {\r\n    searchUser: \"Search for users\",\r\n    noMatches: \"No matches found\", \r\n    inputTooShort: \"Please enter more characters\",\r\n    selectionTooBig: \"You are only allowed to send messages to \" + maxRecipients + \" users at a time\"\r\n};\r\n	\r\n    \r\n    // Инициализация поля \"to\"\r\n    try {\r\n        globalSelect2Field = new Select2Field(\'to\', \'to\', maxRecipients, texts);\r\n        \r\n        // Обновление перед отправкой формы\r\n        var form = document.querySelector(\'form[name=\"input\"]\');\r\n        if (form) {\r\n            form.addEventListener(\'submit\', function(e) {\r\n                if (globalSelect2Field) globalSelect2Field.forceUpdate();\r\n            });\r\n        }\r\n        \r\n    } catch (error) {\r\n        console.error(\'Error initializing Select2 field:\', error);\r\n    }\r\n});\r\n\r\n\r\n</script>\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1469','private_send_tracking','<input type=\"checkbox\" class=\"form-check-input\" name=\"options[readreceipt]\" value=\"1\" tabindex=\"8\" {$optionschecked[\'readreceipt\']} /> {$options_read_receipt}','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1470','private_tracking','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->private[\'pm_tracking\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n\r\n	\r\n	<form action=\"private.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"do_tracking\" />\r\n		\r\n		<div class=\"card border-0 mb-4\">\r\n<div class=\"card-header py-3 bg-nav rounded border-bottom-0\">\r\n		\r\n		<div class=\"row g-2 text-forum\">\r\n			<div class=\"col-1\">\r\n				&nbsp;\r\n			</div>\r\n			<div class=\"col align-self-center\">\r\n				{$lang->private[\'message_title\']} &mdash; {$lang->private[\'sentto\']}\r\n			</div>\r\n			<div class=\"col-3 align-self-center\">\r\n				<span class=\"d-none d-sm-none d-md-none d-lg-inline-block d-xl-inline-block d-xxl-inline-block\">{$lang->private[\'dateread\']}</span>\r\n				<span class=\"float-end\"><input type=\"checkbox\" class=\"form-check-input checkall\" name=\"allbox\" /></span>\r\n			</div>\r\n	</div>\r\n		\r\n			</div>\r\n		</div>\r\n\r\n{$readmessages}\r\n\r\n	<div class=\"card border-0 mb-4\">\r\n<div class=\"card-header py-3 bg-nav rounded border-bottom-0\">\r\n{$stoptrackingread}\r\n</form>\r\n		</div>\r\n		</div>\r\n\r\n\r\n	{$unread_multipage}\r\n		\r\n<form action=\"private.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"do_tracking\" />\r\n	\r\n	<div class=\"card border-0 mb-4\">\r\n<div class=\"card-header py-3 bg-nav rounded border-bottom-0\">\r\n		\r\n		<div class=\"row g-2 text-forum\">\r\n			<div class=\"col-1\">\r\n				&nbsp;\r\n			</div>\r\n			<div class=\"col align-self-center\">\r\n				{$lang->private[\'message_title\']} &mdash; {$lang->private[\'sentto\']}\r\n			</div>\r\n			<div class=\"col-3 align-self-center\">\r\n				<span class=\"d-none d-sm-none d-md-none d-lg-inline-block d-xl-inline-block d-xxl-inline-block\">{$lang->private[\'datesent\']}</span>\r\n				<span class=\"float-end\"><input type=\"checkbox\" class=\"form-check-input checkall\" name=\"allbox\" /></span>\r\n			</div>\r\n	</div>\r\n		\r\n			</div>\r\n		</div>\r\n	\r\n		\r\n{$unreadmessages}\r\n\r\n	<div class=\"card border-0 mb-4\">\r\n<div class=\"card-header py-3 bg-nav rounded border-bottom-0\">\r\n{$stoptrackingunread}\r\n	</div>\r\n	</div>\r\n</form>\r\n</div></div>\r\n	</div>\r\n\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1471','private_tracking_nomessage','<div class=\"ps-3 pe-3 pb-3\">{$no_readmessages}</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1472','private_tracking_readmessage','<div class=\"card mb-0 border-0\">\r\n	<div class=\"card-body pt-0 inline_row\">\r\n	<div class=\"row g-2 pb-3 border-bottom mb-0\">\r\n		<div class=\"col-auto col-sm-auto col-md-auto col-lg-1 col-xl-1 col-xxl-1 align-self-center\">\r\n			<avatarep_uid_[{$readmessage[\'toid\']}]>\r\n				</div>\r\n			<div class=\"col align-self-center\">\r\n				<h6 class=\"mb-0 text-forum\">{$readmessage[\'subject\']}</h6>\r\n				<span class=\"links small\">{$readmessage[\'profilelink\']}</span>\r\n			</div>\r\n			<div class=\"col-auto d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block align-self-center\">\r\n				{$icon} <img src=\"{$theme[\'imgdir\']}/old_pm.png\" alt=\"\" />\r\n			</div>\r\n			<div class=\"col-lg-3 text-muted align-self-center\">\r\n				{$readdate}\r\n				<span class=\"float-end\">\r\n					<input type=\"checkbox\" class=\"form-check-input\" name=\"readcheck[{$readmessage[\'pmid\']}]\" value=\"1\" />\r\n				</span>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1473','private_tracking_readmessage_stop','<div class=\"text-center\"><button type=\"submit\" class=\"btn btn-primary btn-sm\" name=\"stoptracking\" value=\"{$lang->private[\'stop_tracking\']}\"><i class=\"fa-solid fa-xmark\"></i> &nbsp;{$lang->private[\'stop_tracking\']}</button> &nbsp; <a href=\"private.php?action=stopalltracking&amp;my_post_key={$mybb->post_code}\" class=\"btn btn-primary btn-sm\" style=\"color: #ffffff!important;\"><i class=\"fa-solid fa-xmark\"></i> &nbsp;{$lang->private[\'stop_tracking_all\']}</a></div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1474','private_tracking_unreadmessage','<div class=\"card mb-0 border-0\">\r\n	<div class=\"card-body pt-0 inline_row\">\r\n	<div class=\"row g-2 pb-3 border-bottom mb-0\">\r\n		<div class=\"col-auto col-sm-auto col-md-auto col-lg-1 col-xl-1 col-xxl-1 align-self-center\">\r\n			<avatarep_uid_[{$unreadmessage[\'toid\']}]>\r\n				</div>\r\n			<div class=\"col align-self-center\">\r\n				<h6 class=\"mb-0 text-forum\">{$unreadmessage[\'subject\']}</h6>\r\n				<span class=\"links small\">{$unreadmessage[\'profilelink\']}</span>\r\n			</div>\r\n			<div class=\"col-auto d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block align-self-center\">\r\n				{$icon} <img src=\"{$theme[\'imgdir\']}/new_pm.png\" alt=\"\" />\r\n			</div>\r\n			<div class=\"col-lg-3 text-muted align-self-center\">\r\n				{$senddate}\r\n				<span class=\"float-end\">\r\n					<input type=\"checkbox\" class=\"form-check-input\" name=\"unreadcheck[{$unreadmessage[\'pmid\']}]\" value=\"1\" />\r\n				</span>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1475','private_tracking_unreadmessage_stop','<div class=\"text-center\">\r\n	<button type=\"submit\" class=\"btn btn-primary btn-sm\" name=\"stoptrackingunread\" value=\"{$lang->private[\'stop_tracking\']}\"><i class=\"fa-solid fa-xmark\"></i> &nbsp;{$lang->private[\'stop_tracking\']}</button> &nbsp; <button type=\"submit\" class=\"btn btn-primary btn-sm\" name=\"cancel\" value=\"{$lang->private[\'delete\']}\"><i class=\"fa-solid fa-xmark\"></i> &nbsp;{$lang->private[\'delete\']}</button>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1476','redirect','<html>\r\n<head>\r\n<title>{$title}</title>\r\n<meta http-equiv=\"refresh\" content=\"2;URL={$url}\" />\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n<div class=\"container-md pt-5\">\r\n<div class=\"card pt-5 border-0\" style=\"max-width: 100%\">\r\n<div class=\"card-body pt-5\">\r\n	<div class=\"text-dark\"><h3 class=\"mb-0 fw-bold\">{$title}</h3></div>\r\n		<div class=\"alert bg-nav mt-2 mb-2\" style=\"font-size: 16px\">\r\n			{$message} </div>\r\n	<div class=\"text-center\" style=\"font-size: 16px\">\r\n		<a href=\"{$url}\">{$lang->click_no_wait}</a>\r\n	</div>\r\n	</div>\r\n	</div>\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1477','report','<div class=\"modal p-0 m-0\">\r\n	  <form action=\"report.php\" method=\"post\" class=\"reportData_{$id}\" onsubmit=\"return Report.submitReport({$id});\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"do_report\" />\r\n<input type=\"hidden\" name=\"type\" value=\"{$report_type}\" />\r\n<input type=\"hidden\" name=\"pid\" value=\"{$id}\" />\r\n<input type=\"hidden\" name=\"no_modal\" value=\"1\" />\r\n		<div class=\"card border modal_{$id}\" style=\"overflow-y: auto; max-height: 500px;\">\r\n			<div class=\"card-header text-19 fw-bold border-0 py-3\"><i class=\"fa-solid fa-flag\"></i></div>\r\n			<div class=\"card-body\">{$report_reasons}\r\n			</form>\r\n			\r\n			<script type=\"text/javascript\">\r\n<!--\r\n	if($(\"#report_reason option:selected\").attr(\'data-extra\') != 1)\r\n	{\r\n		$(\"#reason\").hide();\r\n	}\r\n\r\n	$(\"#report_reason\").on(\'change\', function()\r\n	{\r\n		if($(this).find(\"option:selected\").attr(\'data-extra\') == 1)\r\n		{\r\n			$(\"#reason\").show();\r\n			return;\r\n		}\r\n\r\n		$(\"#reason\").hide();\r\n	});\r\n// -->\r\n</script>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1478','report_duplicate','<tr>\r\n	<td class=\"trow1\" style=\"border-bottom: 0px\">{$lang->error_report_duplicate}</td>\r\n</tr>\r\n<tr>\r\n	<td class=\"tfoot\" style=\"border-top: 0px\"><input type=\"submit\" class=\"btn btn-primary\" value=\"{$report_title}\" /></td>\r\n</tr>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1479','report_error_nomodal','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$report_title}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n	\r\n\r\n	\r\n	<div class=\"container-md\">\r\n		\r\n		<div class=\"card body bg-white shadow-sm border-0 p-2 p-sm-2 p-md-2 p-lg-3 p-xl-3 p-xxl-3\">\r\n		\r\n	<div class=\"legend mb-4\">{$report_title}</div>\r\n\r\n			\r\n			<div class=\"ps-3 pe-3\">{$error}</div>\r\n\r\n	</div>\r\n</div>\r\n\r\n\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1480','report_reasons','<label class=\"fw-normal\">{$lang->report_reason}</label>\r\n		<select name=\"reason\" id=\"report_reason\" class=\"form-select border form-select-sm pe-5 w-auto\">\r\n			{$reasonslist}\r\n		</select>\r\n<div class=\"mt-3\"></div>\r\n<div id=\"reason\">\r\n<label class=\"text-desc fw-normal\">{$lang->report_reason_other_description}</label>\r\n		<input type=\"text\" class=\"form-control border form-control-sm\" name=\"comment\" size=\"40\" maxlength=\"250\" />\r\n<div class=\"mt-3\"></div>\r\n</div>\r\n\r\n</div>\r\n<div class=\"card-footer text-center\">\r\n<input type=\"submit\" class=\"btn btn-primary btn-sm\" value=\"{$report_title}\" />\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1481','report_thanks','<table border=\"0\" cellspacing=\"{$theme[\'borderwidth\']}\" cellpadding=\"{$theme[\'tablespace\']}\" class=\"tborder\">\r\n	<tr>\r\n		<td class=\"trow1\">{$lang->success_report_voted}</td>\r\n	</tr>\r\n</table>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1490','search','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->search[\'search\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n\r\n	<div class=\"container-md\">\r\n<form action=\"search.php\">\r\n<input type=\"hidden\" name=\"action\" value=\"do_search\" />\r\n	\r\n<div class=\"card\">\r\n<div class=\"card-body\"> \r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->search[\'search_keyword\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->search[\'search_keyword\']}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" class=\"form-control form-control-sm border\" name=\"keywords\" size=\"35\" maxlength=\"250\" />\r\n	\r\n	<div class=\"radio-toolbar mt-2\">\r\n <input type=\"radio\" name=\"postthread\" id=\"postthread\" value=\"1\" checked>\r\n		 <label for=\"postthread\">{$lang->search[\'search_entire_post\']}\r\n  </label>\r\n\r\n\r\n <input type=\"radio\" name=\"postthread\" id=\"postthread2\" value=\"2\" />\r\n		 <label for=\"postthread2\">{$lang->search[\'search_titles_only\']}\r\n		</label>\r\n	</div>\r\n</div>\r\n</div>\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->search[\'search_forums\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->search[\'search_forums\']}\r\n</div>\r\n<div class=\"col\">\r\n{$srchlist}\r\n</div>\r\n</div>\r\n	\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->search[\'search_username\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->search[\'search_username\']}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" class=\"form-control form-control-sm border\" id=\"author\" name=\"author\" size=\"35\" maxlength=\"{$maxnamelength}\" />\r\n<div class=\"form-check mt-1\">\r\n  <input class=\"form-check-input\" type=\"checkbox\" name=\"matchusername\" value=\"1\" id=\"match\" checked>\r\n  <label class=\"form-check-label\" for=\"match\">\r\n    {$lang->search[\'match_username\']}\r\n  </label>\r\n</div>	\r\n</div>\r\n</div>	\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->search[\'search_options\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->search[\'search_options\']}\r\n</div>\r\n<div class=\"col\">\r\n	<div class=\"pb-3 mb-4 border-bottom\">\r\n<div class=\"row\">\r\n	<div class=\"col-auto\">\r\n	<select name=\"findthreadst\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n<option value=\"1\">{$lang->search[\'threads_at_least\']}</option>\r\n<option value=\"2\">{$lang->search[\'threads_at_most\']}</option>\r\n					</select>\r\n	</div>\r\n	<div class=\"col-2\">\r\n		<input type=\"text\" class=\"form-control form-control-sm border\" name=\"numreplies\" size=\"2\" maxlength=\"4\" />\r\n	</div>\r\n	<div class=\"col-auto align-self-center\">\r\n		{$lang->search[\'replies2\']}\r\n	</div>\r\n		</div>\r\n	</div>\r\n		\r\n	<div class=\"pb-3 mb-4 border-bottom\">\r\n	<select name=\"postdate\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n<option value=\"0\">{$lang->search[\'find_anydate\']}</option>\r\n<option value=\"1\">{$lang->search[\'find_yesterday\']}</option>\r\n<option value=\"7\">{$lang->search[\'find_lastweek\']}</option>\r\n<option value=\"14\">{$lang->search[\'find_2weeks\']}</option>\r\n<option value=\"30\">{$lang->search[\'find_month\']}</option>\r\n<option value=\"90\">{$lang->search[\'find_3months\']}</option>\r\n<option value=\"180\">{$lang->search[\'find_6months\']}</option>\r\n<option value=\"365\">{$lang->search[\'find_year\']}</option>\r\n</select>	\r\n		\r\n		<div class=\"radio-toolbar mt-2\">\r\n<input type=\"radio\" name=\"pddir\" id=\"pddir\" value=\"1\" checked>\r\n  <label for=\"pddir\">\r\n    {$lang->search[\'and_newer\']}\r\n  </label>\r\n  <input type=\"radio\" name=\"pddir\" id=\"pddir2\" value=\"0\">\r\n  <label for=\"pddir2\">\r\n    {$lang->search[\'and_older\']}\r\n  </label>\r\n		</div>\r\n	</div>\r\n		\r\n	{$prefixselect}\r\n		\r\n</div>\r\n</div>		\r\n	\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->search[\'sorting_options\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->search[\'sorting_options\']}\r\n</div>\r\n<div class=\"col\">\r\n\r\n	<select name=\"sortby\" class=\"form-select form-select-sm border w-auto pe-5 mb-1\">\r\n<option value=\"lastpost\">{$lang->search[\'sort_lastpost\']}</option>\r\n<option value=\"starter\">{$lang->search[\'sort_author\']}</option>\r\n<option value=\"forum\">{$lang->search[\'sort_forum\']}</option>\r\n<option value=\"views\">{$lang->search[\'sort_views\']}</option>\r\n<option value=\"replies\">{$lang->search[\'sort_replies\']}</option>\r\n</select> \r\n\r\n	<div class=\"radio-toolbar mt-2\">\r\n	 <input type=\"radio\" name=\"sortordr\" id=\"1\" value=\"asc\">\r\n  <label for=\"1\">\r\n    {$lang->search[\'sort_asc\']}\r\n  </label>	\r\n		\r\n  <input type=\"radio\" name=\"sortordr\" id=\"2\" value=\"desc\" checked>\r\n  <label for=\"2\">\r\n    {$lang->search[\'sort_desc\']}\r\n  </label>\r\n	</div>\r\n	\r\n	\r\n</div>\r\n</div>	\r\n	\r\n	{$moderator_options}\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->search[\'display_options\']}</div>\r\n<div class=\"row g-3 m-auto pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->search[\'display_options\']}\r\n</div>\r\n<div class=\"col\">\r\n	<label>{$lang->search[\'show_results_as\']}</label>\r\n			\r\n\r\n	<div class=\"radio-toolbar\">\r\n			 <input type=\"radio\" name=\"showresults\" id=\"show1\" value=\"threads\" checked>\r\n  <label for=\"show1\">\r\n    {$lang->search[\'show_results_threads\']}\r\n  </label>\r\n	<input type=\"radio\" name=\"showresults\" id=\"show2\" value=\"posts\" />\r\n  <label for=\"show2\">\r\n    {$lang->search[\'show_results_posts\']}\r\n  </label>\r\n	</div>\r\n\r\n\r\n</div>\r\n</div>	\r\n\r\n			\r\n\r\n	\r\n			\r\n	</div>\r\n			<div class=\"card-footer text-center\">\r\n			<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->search[\'search\']}\"><i class=\"fa-solid fa-magnifying-glass\"></i> &nbsp;{$lang->search[\'search\']}</button>\r\n	</div>\r\n	</div>\r\n	</div>\r\n		\r\n\r\n\r\n\r\n</form>\r\n{$footer}\r\n<link rel=\"stylesheet\" href=\"{$BASEURL}/scripts/select2/select2-2.css?ver=1807\">\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/select2/select2.min.js?ver=1806\"></script>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n\r\n	MyBB.select2();\r\n	$(\"#author\").select2({\r\n		placeholder: \"{$lang->search[\'search_user\']}\",\r\n		minimumInputLength: 2,\r\n		multiple: false,\r\n		allowClear: true,\r\n		ajax: { // instead of writing the function to execute the request we use Select2\'s convenient helper\r\n			url: \"xmlhttp.php?action=get_users\",\r\n			dataType: \'json\',\r\n			data: function (term, page) {\r\n				return {\r\n					query: term, // search term\r\n				};\r\n			},\r\n			results: function (data, page) { // parse the results into the format expected by Select2.\r\n				// since we are using custom formatting functions we do not need to alter remote JSON data\r\n				return {results: data};\r\n			}\r\n		},\r\n		initSelection: function(element, callback) {\r\n			var value = $(element).val();\r\n			if (value !== \"\") {\r\n				callback({\r\n					id: value,\r\n					text: value\r\n				});\r\n			}\r\n		},\r\n	});\r\n\r\n// -->\r\n</script>\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1491','search_forumlist','<select name=\"forums[]\" id=\"select\" class=\"form-select form-select-sm border mb-4\" multiple=\"multiple\">\r\n<option value=\"all\" selected=\"selected\">{$lang->search[\'search_all_forums\']}</option>\r\n<option value=\"all\">----------------------</option>\r\n{$forumlistbits}\r\n</select>\r\n\r\n<script>\r\n	var select = document.getElementById(\'select\');\r\nselect.size = select.length;\r\n</script>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1492','search_moderator_options','<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->search[\'mod_options\']}</div>\r\n<div class=\"row g-3 m-auto pb-4 border-bottom pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->search[\'mod_options\']}\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"row\">\r\n	<div class=\"col-auto align-self-center\">\r\n\r\n<select name=\"visible\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n<option value=\"\">{$lang->search[\'display_all\']}</option>\r\n<option value=\"1\">{$lang->search[\'display_only_approved\']}</option>\r\n<option value=\"0\">{$lang->search[\'display_only_unapproved\']}</option>\r\n<option value=\"-1\">{$lang->search[\'display_only_softdeleted\']}</option>\r\n</select>\r\n		\r\n	</div>\r\n	<div class=\"col-auto align-self-center\">\r\n\r\n{$lang->search[\'results\']}\r\n		\r\n	</div>\r\n	</div>\r\n</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1493','search_results_inlinemodcol','\r\n<div class=\"form-check form-switch float-end\">\r\n    <input class=\"form-check-input\" type=\"checkbox\" name=\"allbox\" id=\"allbox\" onclick=\"inlineModeration.checkAll(this);\">\r\n</div>\r\n','2','1837','','1720609281');
