INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1502','search_results_threads_inlinemoderation','<div class=\"card mt-4 border-0\">\r\n	<div class=\"card-body bg-nav\">\r\n\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/inline_moderation.js?ver=1821\"></script>\r\n		<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"fid\" value=\"0\" />\r\n<input type=\"hidden\" name=\"searchid\" value=\"{$sid}\" />\r\n<input type=\"hidden\" name=\"modtype\" value=\"inlinethread\" />\r\n			<div class=\"row g-1\">\r\n				<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n					&nbsp;\r\n				</div>\r\n				<div class=\"col-auto align-self-center\">\r\n<select name=\"action\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n	<optgroup label=\"{$lang->search[\'standard_mod_tools\']}\">\r\n		<option value=\"multiclosethreads\">{$lang->search[\'close_threads\']}</option>\r\n		<option value=\"multiopenthreads\">{$lang->search[\'open_threads\']}</option>\r\n		<option value=\"multistickthreads\">{$lang->search[\'stick_threads\']}</option>\r\n		<option value=\"multiunstickthreads\">{$lang->search[\'unstick_threads\']}</option>\r\n		<option value=\"multisoftdeletethreads\">{$lang->search[\'soft_delete_threads\']}</option>\r\n		<option value=\"multirestorethreads\">{$lang->search[\'restore_threads\']}</option>\r\n		<option value=\"multideletethreads\">{$lang->search[\'delete_threads\']}</option>\r\n		<option value=\"multimovethreads\">{$lang->search[\'move_threads\']}</option>\r\n		<option value=\"multiapprovethreads\">{$lang->search[\'approve_threads\']}</option>\r\n		<option value=\"multiunapprovethreads\">{$lang->search[\'unapprove_threads\']}</option>\r\n	</optgroup>\r\n	{$customthreadtools}\r\n</select>\r\n				</div>\r\n				<div class=\"col-auto align-self-center\">\r\n<input type=\"submit\" class=\"btn btn-primary btn-sm\" name=\"go\" value=\"{$lang->search[\'inline_go\']} ({$inlinecount})\" id=\"inline_go\" />\r\n				</div>\r\n				<div class=\"col-auto align-self-center\">\r\n<input type=\"button\" onclick=\"inlineModeration.clearChecked();\" value=\"{$lang->search[\'clear\']}\" class=\"btn btn-primary btn-sm\" />\r\n				</div>\r\n				<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n					&nbsp;\r\n				</div>\r\n			</div>\r\n<input type=\"hidden\" name=\"url\" value=\"{$return_url}\" />\r\n<input type=\"hidden\" name=\"inlinetype\" value=\"search\" />\r\n</form>\r\n<script type=\"text/javascript\">\r\n<!--\r\n	var go_text = \"{$lang->search[\'inline_go\']}\";\r\n	var all_text = \"{$threadcount}\";\r\n	var inlineType = \"search\";\r\n	var inlineId = \'{$sid}\';\r\n// -->\r\n</script>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1503','search_results_threads_thread','<div class=\"card border-bottom border-0 rounded-0\">\r\n	<div class=\"card-body py-0 px-1 inline_row\">\r\n<div class=\"row py-2\">\r\n		<div class=\"col align-self-center ms-2\">\r\n			\r\n			\r\n	<h6 class=\"mb-0 text-forum\">{$prefix} {$thread[\'threadprefix\']}<a href=\"{$thread_link}{$highlight}\" class=\"{$inline_edit_class} {$new_class}\" id=\"tid_{$inline_edit_tid}\">{$thread[\'subject\']}</a>{$thread[\'multipage\']}</h6>\r\n			<div class=\"links small\"><span class=\"text-muted\">{$lang->search[\'by\']}</span> {$thread[\'profilelink\']} <span class=\"text-muted\">{$lang->search[\'forum\']}</span> {$thread[\'forumlink\']}</div>\r\n		</div>\r\n			\r\n		<div class=\"col-1 d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block align-self-center text-center\">\r\n			\r\n			<h6 class=\"mb-0\">{$thread[\'replies\']}</h6><span class=\"text-muted small\">{$lang->search[\'replies\']}</span>\r\n			\r\n		</div>\r\n			\r\n		<div class=\"col-12 col-sm-12 col-md-12 col-lg-3 col-xl-3 col-xxl-3 mt-3 mt-sm-3 mt-md-3 mt-lg-0\">\r\n			<div class=\"row\">\r\n				<div class=\"col-auto align-self-center\">\r\n					<avatarep_uid_[{$thread[\'lastposteruid\']}]>\r\n				</div>\r\n				<div class=\"col align-self-center me-2\">{$lastposterlink}<br />\r\n				<span class=\"text-desc small\">{$lastpostdate}</span> {$inline_mod_checkbox}\r\n					</div>\r\n				</div>\r\n				\r\n				\r\n				\r\n				\r\n			</div>\r\n			</div>\r\n	</div>\r\n			</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1504','sendthread','<html>\r\n<head>\r\n<title>{$threadprefix[\'prefix\']} {$thread[\'subject\']} - {$lang->send_thread}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n	\r\n	<div class=\"container-md\">\r\n		\r\n{$errors}\r\n<form action=\"sendthread.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"card\">\r\n					\r\n<div class=\"card-body\">\r\n					\r\n					{$from_email}\r\n					\r\n					<div class=\"pb-3 mb-3 border-bottom\">\r\n					 <label for=\"email\">{$lang->recipient}</label>\r\n    <input type=\"text\" name=\"email\" class=\"form-control form-control-sm border\" id=\"email\" value=\"{$email}\" />\r\n					</div>\r\n					\r\n					<div class=\"pb-3 mb-3 border-bottom\">\r\n						<label for=\"subject\">{$lang->subject}</label>\r\n						<input type=\"text\" class=\"form-control border form-control-sm border\" id=\"subject\" size=\"50\" name=\"subject\" value=\"{$subject}\" />\r\n					</div>\r\n					\r\n					\r\n						<label for=\"message\">{$lang->message}</label>\r\n						<textarea cols=\"50\" style=\"resize: none\" rows=\"10\" class=\"form-control border form-control-sm border\" id=\"message\" name=\"message\">{$message}</textarea>\r\n					\r\n					\r\n					{$captcha}\r\n					\r\n	</div>\r\n					<div class=\"card-footer text-center\">\r\n						<input type=\"hidden\" name=\"action\" value=\"do_sendtofriend\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n<input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->send_thread}\" />\r\n					</div>\r\n	</div>\r\n	\r\n	</form>\r\n	</div>\r\n\r\n\r\n\r\n\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1505','sendthread_fromemail','<div class=\"pb-3 mb-3 border-bottom\">\r\n					 <label for=\"fromname\">{$lang->your_name}</label>\r\n    <input type=\"text\" name=\"fromname\" class=\"form-control border form-control-sm\" id=\"fromname\" value=\"{$fromname}\" />\r\n					</div>\r\n\r\n<div class=\"pb-3 mb-3 border-bottom\">\r\n					 <label for=\"fromemail\">{$lang->your_email}</label>\r\n    <input type=\"text\" name=\"fromemail\" class=\"form-control border form-control-sm\" id=\"fromemail\" value=\"{$fromemail}\" />\r\n					</div>','2','1837','','1720609281');
