INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1512','showthread','<html>\r\n<head>\r\n<title>{$thread[\'subject\']}</title>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n	var quickdelete_confirm = \"Are you sure you want to delete this post?\";\r\n	var quickrestore_confirm = \"Are you sure you want to restore this post?\";\r\n	var allowEditReason = \"1\";\r\n	var thread_deleted = \"{$thread_deleted}\";\r\n	var visible_replies = \"{$thread[\'replies\']}\";\r\n	\r\n	lang.save_changes = \"Save Changes\";\r\n	lang.cancel_edit = \"Cancel Edit\";\r\n	lang.quick_edit_update_error = \"There was an error editing your reply:\";\r\n	lang.quick_reply_post_error = \"There was an error posting your reply:\";\r\n	lang.quick_delete_error = \"There was an error deleting your reply:\";\r\n	lang.quick_delete_success = \"The post was deleted successfully.\";\r\n	lang.quick_delete_thread_success = \"The thread was deleted successfully.\";\r\n	lang.quick_restore_error = \"There was an error restoring your reply:\";\r\n	lang.quick_restore_success = \"The post was restored successfully.\";\r\n	lang.editreason = \"Edit Reason\";\r\n	lang.post_deleted_error = \"You can not perform this action to a deleted post.\";\r\n	lang.softdelete_thread = \"Soft Delete Thread\";\r\n	lang.restore_thread = \"Restore Thread\";\r\n	const forumBaseUrl = \"{$test}\";\r\n// -->\r\n</script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/thread.js?ver=1827\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/toast.js\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/edit_post.js\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/delete_post.js\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/report_post.js\"></script>\r\n\r\n\r\n</head>\r\n<body>\r\n{$header}\r\n\r\n	\r\n	\r\n<div class=\"container-md\">\r\n	\r\n\r\n	\r\n<div class=\"row mb-3 p-0 m-0\">\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg col-xl col-xxl p-0 align-self-center text-center text-sm-center text-md-center text-lg-start text-xl-start text-xxl-start mt-3 mt-sm-3 mt-md-3 mt-lg-0 mt-xl-0 mt-xxl-0\">\r\n		{$multipage}\r\n	</div>\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg-auto col-xl-auto col-xxl-auto m-0 p-0 text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center order-first order-sm-first order-md-first order-lg-last order-xl-last order-xxl-last\">\r\n		\r\n		{$addremovesubscription} {$newreply}\r\n			\r\n		\r\n	</div>\r\n	</div>\r\n\r\n{$pollbox}\r\n	<div id=\"posts\">{$posts}</div>\r\n	\r\n	\r\n	\r\n\r\n	\r\n	\r\n	<div class=\"row mt-3 mb-3 p-0 m-0\">\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg col-xl col-xxl p-0 align-self-center text-center text-sm-center text-md-center text-lg-start text-xl-start text-xxl-start mb-3 mb-sm-3 mb-md-3 mb-lg-0 mb-xl-0 mb-xxl-0\">\r\n		{$multipage}\r\n	</div>\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg-auto col-xl-auto col-xxl-auto m-0 p-0 text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center\">\r\n		\r\n		 {$newreply}\r\n			\r\n		\r\n	</div>\r\n	</div>\r\n	\r\n	\r\n{$quickreply}\r\n\r\n<div class=\"container-md\">	\r\n<div class=\"row mt-5 m-0 p-0 border-top border-bottom\">\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg-5 col-xl-5 col-xxl-5 align-self-center py-3\">\r\n		{$search_thread}\r\n	</div>\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg col-xl col-xxl text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center py-3\"><a href=\"{$next_oldest_link}\" class=\"links\"><i class=\"fa-solid fa-angles-left\"></i> {$lang->showthread[\'next_oldest\']}</a> &nbsp;&nbsp;&nbsp;&nbsp; <a href=\"{$next_newest_link}\" class=\"links\">{$lang->showthread[\'next_newest\']} <i class=\"fa-solid fa-angles-right\"></i></a>\r\n	</div>\r\n	\r\n	</div>\r\n	\r\n		<div class=\"row m-0 p-0 mt-2 text-end\">\r\n			<div class=\"col-12 text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center\">\r\n					{$addpoll}{$printthread}&nbsp;&nbsp; {$sendthread}\r\n			</div></div>\r\n	\r\n	{$moderationoptions}\r\n	\r\n		{$usersbrowsing}\r\n	\r\n</div>\r\n	\r\n\r\n	</div>\r\n	<script type=\"text/javascript\">\r\n		var thread_deleted = \"{$thread_deleted}\";\r\n		if(thread_deleted == \"1\")\r\n		{\r\n			$(\"#quick_reply_form, .new_reply_button, .thread_tools, .inline_rating\").hide();\r\n			$(\"#moderator_options_selector option.option_mirage\").attr(\"disabled\",\"disabled\");\r\n		}\r\n	</script>\r\n	\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1513','showthread_add_poll','<a href=\"polls.php?action=newpoll&amp;tid={$tid}\" title=\"{$lang->showthread[\'add_poll_to_thread\']}\" class=\"links\"><i class=\"fa-solid fa-square-poll-vertical\"></i></a> &nbsp;&nbsp;','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1514','showthread_inlinemoderation','<div class=\"col-lg\">\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/inline_moderation.js?ver=1821\"></script>\r\n<form action=\"moderation.php\" method=\"post\" style=\"margin-top: 0; margin-bottom: 0;\" id=\"inlinemoderation_options\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n<input type=\"hidden\" name=\"modtype\" value=\"inlinepost\" />\r\n	<div class=\"row g-1\">\r\n		<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n			&nbsp;\r\n		</div>\r\n		<div class=\"col-auto\">\r\n<select name=\"action\" id=\"inlinemoderation_options_selector\" class=\"form-select form-select-sm border w-auto pe-5\">\r\n{$standardposttools}\r\n{$customposttools}\r\n</select>\r\n		</div>\r\n		<div class=\"col-auto\">\r\n		\r\n<input type=\"submit\" class=\"btn btn-sm btn-primary\" name=\"go\" value=\"{$lang->showthread[\'go\']} ({$inlinecount})\" id=\"inline_go\" /> <input type=\"button\" class=\"btn btn-sm btn-primary\" onclick=\"inlineModeration.clearChecked();\" value=\"{$lang->showthread[\'clear\']}\" />\r\n</form>\r\n	</div>\r\n	</div>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n	var go_text = \"{$lang->showthread[\'inline_go\']}\";\r\n	var all_text = \"{$threadcount}\";\r\n	var inlineType = \"thread\";\r\n	var inlineId = {$tid};\r\n\r\n	// ЗАМЕНА jQuery на чистый JavaScript\r\n	document.addEventListener(\'DOMContentLoaded\', function() {\r\n		var selector = document.getElementById(\"inlinemoderation_options_selector\");\r\n		var form = document.getElementById(\"inlinemoderation_options\");\r\n		\r\n		if(selector && form) {\r\n			selector.addEventListener(\'change\', function() {\r\n				form.dispatchEvent(new Event(\'submit\'));\r\n			});\r\n		}\r\n	});\r\n// -->\r\n</script>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1515','showthread_moderationoptions','<div class=\"row mt-5 g-1 m-0 py-3 border-top border-bottom\">\r\n	<div class=\"col-lg-6\">\r\n\r\n<form action=\"moderation.php\" method=\"post\" style=\"margin-top: 0; margin-bottom: 0;\" id=\"moderator_options\">\r\n	<input type=\"hidden\" name=\"modtype\" value=\"thread\" />\r\n	<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n	<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"row g-1 text-lg-start\">\r\n<div class=\"col-auto\">\r\n	<select name=\"action\" id=\"moderator_options_selector\" class=\"form-select form-select-sm w-auto pe-5\">\r\n		<option value=\"delayedmoderation\">{$lang->showthread[\'delayed_moderation\']}</option>\r\n		{$standardthreadtools}\r\n		{$customthreadtools}\r\n	</select>\r\n</div>\r\n<div class=\"col-auto\">\r\n{$gobutton}\r\n</div>\r\n</div>\r\n</form>\r\n<script type=\"text/javascript\">\r\n<!--\r\n	// ЗАМЕНА jQuery на чистый JavaScript\r\n	document.addEventListener(\'DOMContentLoaded\', function() {\r\n		var selector = document.getElementById(\"moderator_options_selector\");\r\n		var form = document.getElementById(\"moderator_options\");\r\n		\r\n		if(selector && form) {\r\n			selector.addEventListener(\'change\', function() {\r\n				form.dispatchEvent(new Event(\'submit\'));\r\n			});\r\n		}\r\n	});\r\n//-->\r\n</script>\r\n		\r\n	</div>\r\n{$inlinemod}\r\n	</div>','2','1837','','1720609281');
