INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1543','stats','<html>\r\n<head>\r\n    <title>{$SITENAME} - {$lang->stats[\'board_stats\']}</title>\r\n   \r\n    <!-- Bootstrap Icons -->\r\n    <link rel=\"stylesheet\" href=\"{$BASEURL}/include/templates/default/style/bootstrap-icons.css\">\r\n    <style>\r\n        .card-hover:hover {\r\n            transform: translateY(-3px);\r\n            box-shadow: 0 0.5rem 1rem rgba(0,0,0,.1);\r\n            transition: all 0.3s ease;\r\n        }\r\n        .icon-blue {\r\n            color: #0d6efd; /* Bootstrap primary blue */\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n\r\n<div class=\"container my-5\">\r\n\r\n    <div class=\"row\">\r\n        <div class=\"col-lg-9\">\r\n\r\n            <div class=\"card shadow-sm mb-4 border-0 card-hover\">\r\n                <div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n                    <i class=\"bi bi-chat-left-text icon-blue me-1\"></i> {$lang->stats[\'most_replied_threads\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    {$mostreplies}\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"card shadow-sm mb-4 border-0 card-hover\">\r\n                <div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n                    <i class=\"bi bi-eye icon-blue me-1\"></i> {$lang->stats[\'most_viewed_threads\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    {$mostviews}\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n        <div class=\"col-lg-3\">\r\n\r\n            <div class=\"card shadow-sm mb-4 border-0 card-hover\">\r\n                <div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n                    <i class=\"bi bi-bar-chart icon-blue me-1\"></i> {$lang->stats[\'totals\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-pencil icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'posts\']}</span> <span class=\"fw-bold\">{$stats[\'numposts\']}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-card-text icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'threads\']}</span> <span class=\"fw-bold\">{$stats[\'numthreads\']}</span>\r\n                    </div>\r\n                    <div class=\"py-2\">\r\n                        <i class=\"bi bi-people icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'members\']}</span> <span class=\"fw-bold\">{$stats[\'numusers\']}</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"card shadow-sm mb-4 border-0 card-hover\">\r\n                <div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n                    <i class=\"bi bi-graph-up icon-blue me-1\"></i> {$lang->stats[\'averages\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-pencil icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'ppd\']}</span> <span class=\"fw-bold\">{$postsperday}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-card-text icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'tpd\']}</span> <span class=\"fw-bold\">{$threadsperday}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-person-plus icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'mpd\']}</span> <span class=\"fw-bold\">{$membersperday}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-chat-dots icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'ppm\']}</span> <span class=\"fw-bold\">{$postspermember}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-threads icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'tpm\']}</span> <span class=\"fw-bold\">{$threadspermember}</span>\r\n                    </div>\r\n                    <div class=\"py-2\">\r\n                        <i class=\"bi bi-arrow-return-right icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'rpt\']}</span> <span class=\"fw-bold\">{$repliesperthread}</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"card shadow-sm mb-4 border-0 card-hover\">\r\n                <div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n                    <i class=\"bi bi-info-circle icon-blue me-1\"></i> {$lang->stats[\'averages\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-person-check icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'newest_member\']}</span> <span class=\"fw-bold\">{$stats[\'newest_user\']}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-percent icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'members_posted\']}</span> <span class=\"fw-bold\">{$havepostedpercent}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-star icon-blue me-1\"></i> {$todays_top_poster}\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-fire icon-blue me-1\"></i> {$popular_forum}\r\n                    </div>\r\n                    <div class=\"py-2\">\r\n                        <i class=\"bi bi-person-heart icon-blue me-1\"></i> {$top_referrer}\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n\r\n</div>\r\n</body>\r\n</html>\r\n','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1544','stats_thread','<div class=\"row py-2 border-bottom\">\r\n	<div class=\"col-lg-10\">\r\n		<h6 class=\"mb-0\"><a href=\"{$thread[\'threadlink\']}\">{$thread[\'subject\']}</a></h6>\r\n	</div>\r\n	<div class=\"col-lg-2 text-lg-end\">\r\n		{$numberbit} {$numbertype}\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1545','usercp','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{$SITENAME} - {$lang->usercp[\'user_cp\']}</title>\r\n   \r\n    <style>\r\n        .user-stats-card {\r\n            border-radius: 12px;\r\n            border: none;\r\n            background: linear-gradient(135deg, #ffffff 0%, #f8f9fa 100%);\r\n            color: #2c3e50;\r\n        }\r\n        \r\n        .user-avatar {\r\n            width: 100px;\r\n            height: 100px;\r\n            border-radius: 50%;\r\n            object-fit: cover;\r\n            border: 3px solid #ffffff;\r\n        }\r\n        \r\n        .stat-item {\r\n            transition: all 0.3s ease;\r\n            padding: 12px 0;\r\n            display: flex;\r\n            align-items: center;\r\n        }\r\n        \r\n        .stat-item:hover {\r\n            background-color: rgba(0,0,0,0.03);\r\n            padding-left: 15px;\r\n            border-radius: 8px;\r\n        }\r\n        \r\n        .username-display {\r\n            font-size: 1.4rem;\r\n            font-weight: 600;\r\n            color: #2c3e50;\r\n        }\r\n        \r\n        .stat-label {\r\n            color: #6c757d;\r\n            font-weight: 500;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            flex: 1;\r\n        }\r\n        \r\n        .stat-value {\r\n            color: #2c3e50;\r\n            font-weight: 600;\r\n        }\r\n        \r\n        .border-custom {\r\n            border-color: #e9ecef !important;\r\n        }\r\n        \r\n        .badge-status {\r\n            background: #28a745;\r\n            color: white;\r\n            padding: 4px 12px;\r\n            border-radius: 15px;\r\n            font-size: 0.8rem;\r\n        }\r\n        \r\n        .icon-wrapper {\r\n            width: 20px;\r\n            text-align: center;\r\n            color: #667eea;\r\n        }\r\n        \r\n        .icon-user {\r\n            color: #667eea;\r\n        }\r\n        \r\n        .icon-post {\r\n            color: #4CAF50;\r\n        }\r\n        \r\n        .icon-comment {\r\n            color: #2196F3;\r\n        }\r\n        \r\n        .icon-bonus {\r\n            color: #FF9800;\r\n        }\r\n        \r\n        .icon-email {\r\n            color: #9C27B0;\r\n        }\r\n        \r\n        .icon-date {\r\n            color: #607D8B;\r\n        }\r\n        \r\n        .icon-group {\r\n            color: #E91E63;\r\n        }\r\n    </style>\r\n</head>\r\n\r\n<div class=\"container-md py-4\">\r\n    <div class=\"row g-4\">\r\n        <!-- Навигационная панель -->\r\n        <div class=\"col-12 col-lg-3\">\r\n            <div class=\"sticky-top\" style=\"top: 20px;\">\r\n                {$usercpnav}\r\n            </div>\r\n        </div>\r\n        \r\n        <!-- Основной контент -->\r\n        <div class=\"col\">\r\n            <div class=\"card user-stats-card mb-4\">\r\n                <div class=\"card-body p-4\">\r\n                    <div class=\"row align-items-center\">\r\n                        <!-- Аватар -->\r\n                        <div class=\"col-auto text-center\">\r\n                            \r\n                                {$currentavatar}\r\n                                <div class=\"position-absolute bottom-0 end-0 bg-success rounded-circle border border-2 border-white\" \r\n                                     style=\"width: 20px; height: 20px;\"></div>\r\n                           \r\n                            <div class=\"mt-2\">\r\n                                <span class=\"badge-status\">Online</span>\r\n                            </div>\r\n                        </div>\r\n                        \r\n                        <!-- Статистика пользователя -->\r\n                        <div class=\"col\">\r\n                            <!-- Имя пользователя -->\r\n                            <div class=\"stat-item border-bottom border-custom mb-3\">\r\n                                <div class=\"d-flex align-items-center\">\r\n                                    <i class=\"fas fa-user icon-user me-3\"></i>\r\n                                    <div class=\"username-display\">{$username}</div>\r\n                                </div>\r\n                            </div>\r\n                            \r\n                            <!-- Статистика в две колонки -->\r\n                            <div class=\"row\">\r\n                                <div class=\"col-md-6\">\r\n                                    <!-- Количество сообщений -->\r\n                                    <div class=\"stat-item border-bottom border-custom d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-comment icon-post\"></i>\r\n                                            {$lang->usercp[\'postnum\']}\r\n                                        </span>\r\n                                        <a href=\"search.php?action=finduser&amp;uid={$CURUSER[\'id\']}\" class=\"stat-value text-decoration-none\">\r\n                                            {$mybb->user[\'posts\']} {$ss}\r\n                                        </a>\r\n                                    </div>\r\n                                    \r\n                                    <!-- Комментарии -->\r\n                                    <div class=\"stat-item border-bottom border-custom d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-comments icon-comment\"></i>\r\n                                            {$lang->usercp[\'comentsss\']}\r\n                                        </span>\r\n                                        <a href=\"userhistory.php?action=viewcomments&id={$CURUSER[\'id\']}\" class=\"stat-value text-decoration-none\">\r\n                                            {$com}\r\n                                        </a>\r\n                                    </div>\r\n                                    \r\n                                    <!-- Бонусные баллы -->\r\n                                    <div class=\"stat-item border-bottom border-custom d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-star icon-bonus\"></i>\r\n                                            {$lang->usercp[\'bpoints\']}\r\n                                        </span>\r\n                                        <a href=\"mybonus.php\" class=\"stat-value text-decoration-none\">\r\n                                            {$bonus}\r\n                                        </a>\r\n                                    </div>\r\n                                </div>\r\n                                \r\n                                <div class=\"col-md-6\">\r\n                                    <!-- Email -->\r\n                                    <div class=\"stat-item border-bottom border-custom d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-envelope icon-email\"></i>\r\n                                            {$lang->usercp[\'email\']}\r\n                                        </span>\r\n                                        <span class=\"stat-value\">{$CURUSER[\'email\']}</span>\r\n                                    </div>\r\n                                    \r\n                                    <!-- Дата регистрации -->\r\n                                    <div class=\"stat-item border-bottom border-custom d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-calendar-alt icon-date\"></i>\r\n                                            {$lang->usercp[\'registration_date\']}\r\n                                        </span>\r\n                                        <span class=\"stat-value\">{$regdate}</span>\r\n                                    </div>\r\n                                    \r\n                                    <!-- Основная группа -->\r\n                                    <div class=\"stat-item d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-users icon-group\"></i>\r\n                                            {$lang->usercp[\'primary_usergroup\']}\r\n                                        </span>\r\n                                        <span class=\"stat-value\">{$usergroup}</span>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1546','usercp_addsubscription_thread','<html>\r\n<head>\r\n<title>{$lang->usercp[\'subscribe_to_thread\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n<form action=\"usercp.php\" method=\"post\" name=\"input\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"do_addsubscription\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$thread[\'tid\']}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-3 d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">	\r\n	<!-- offcanvas -->\r\n				<div class=\"d-block d-sm-block d-md-block d-lg-none d-xl-none d-xxl-none\">\r\n				<button class=\"btn btn-primary mb-3\" type=\"button\" data-bs-toggle=\"offcanvas\" data-bs-target=\"#offcanvasExample\" aria-controls=\"offcanvasExample\">\r\n  <i class=\"fa-solid fa-circle-arrow-left\"></i> &nbsp;{$lang->ucpmenu}\r\n</button>\r\n				\r\n				<div class=\"offcanvas offcanvas-start\" tabindex=\"-1\" id=\"offcanvasExample\" aria-labelledby=\"offcanvasExampleLabel\">\r\n  <div class=\"offcanvas-header\">\r\n    <h5 class=\"offcanvas-title\" id=\"offcanvasExampleLabel\">{$lang->usercp[\'ucp_nav_menu\']}</h5>\r\n    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"offcanvas\" aria-label=\"Close\"></button>\r\n  </div>\r\n  <div class=\"offcanvas-body\">\r\n    <div><ul class=\"list-group list-group-flush\">\r\n		{$usercpnav}</ul>\r\n    </div>\r\n  </div>\r\n</div>\r\n				</div>\r\n				<!-- /offcanvas -->\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	\r\n	<div class=\"legend mb-4\">{$lang->usercp[\'subscribe_to_thread\']}</div>\r\n\r\n	<div class=\"ps-3 pe-3\"><strong>{$lang->usercp[\'notification_method\']}</strong></div>\r\n\r\n	<div class=\"row ps-3 pe-3 mt-4\">\r\n		<div class=\"col-auto align-self-top text-center\">\r\n			\r\n			<input type=\"radio\" name=\"notification\" id=\"notification_none\" class=\"form-check-input\" value=\"0\" {$notification_none_checked} />\r\n			\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n		<strong>{$lang->usercp[\'no_notification\']}</strong><br /><span class=\"text-muted\">{$lang->usercp[\'no_notification_desc\']}</span>\r\n		</div>\r\n	</div>\r\n	\r\n	<div class=\"row ps-3 pe-3 mt-2\">\r\n		<div class=\"col-auto align-self-top text-center\">\r\n			\r\n			<input type=\"radio\" class=\"form-check-input\" name=\"notification\" id=\"notification_email\" value=\"1\" {$notification_email_checked} />\r\n			\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n		<strong>{$lang->usercp[\'email_notification\']}</strong><br /><span class=\"text-muted\">{$lang->usercp[\'email_notification_desc\']}</span>\r\n		</div>\r\n	</div>\r\n	\r\n	<div class=\"row ps-3 pe-3 mt-2\">\r\n		<div class=\"col-auto align-self-top text-center\">\r\n			\r\n			<input type=\"radio\" class=\"form-check-input\" name=\"notification\" id=\"notification_pm\" value=\"2\" {$notification_pm_checked} />\r\n			\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n		<strong>{$lang->usercp[\'pm_notification\']}</strong><br /><span class=\"text-muted\">{$lang->usercp[\'pm_notification_desc\']}</span>\r\n		</div>\r\n	</div>\r\n\r\n<div class=\"mt-4 text-end ps-3 pe-3\">\r\n	<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n<input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->usercp[\'do_subscribe\']}\" tabindex=\"3\" accesskey=\"s\" />\r\n	</div>\r\n<div class=\"d-block d-sm-block d-md-block d-lg-none d-xl-none d-xxl-none\">\r\n	<input type=\"submit\" class=\"btn btn-primary\" style=\"width: 100%\" name=\"submit\" value=\"{$lang->usercp[\'do_subscribe\']}\" tabindex=\"3\" accesskey=\"s\" />\r\n</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n</form>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1547','usercp_attachments','<html>\r\n<head>\r\n	<title>{$SITENAME} - {$lang->usercp[\'attachments_manager\']}</title>\r\n	\r\n</head>\r\n<body>\r\n	\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n	\r\n					<form action=\"usercp.php\" method=\"post\" name=\"attachmentsmanager\">\r\n					<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n		<div class=\"card mb-4\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n		{$lang->usercp[\'attachments_manager\']} <span class=\"float-end\"><input type=\"checkbox\" name=\"allbox\" class=\"form-check-input checkall\" /></span>\r\n	</div>\r\n	<div class=\"card-body\">\r\n		{$usagenote}\r\n		{$attachments}\r\n		\r\n			</div>\r\n			<div class=\"card-footer text-center\">\r\n				{$delete_button}\r\n			</div>\r\n						</div></form>\r\n						\r\n						{$multipage}\r\n	\r\n	<div class=\"card\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n		\r\n		{$lang->usercp[\'attachments_stats\']}\r\n		\r\n		</div>\r\n	<div class=\"card-body\">\r\n		\r\n		\r\n				<div class=\"py-2 border-bottom\"><span class=\"text-muted\">{$lang->usercp[\'attachstats_attachs\']}</span> {$totalattachments}</div>\r\n		\r\n		<div class=\"py-2 border-bottom\"><span class=\"text-muted\">{$lang->usercp[\'attachstats_spaceused\']}</span> {$friendlyusage}</div>\r\n		\r\n		<div class=\"py-2 border-bottom\"><span class=\"text-muted\">{$lang->usercp[\'attachstats_quota\']}</span> {$attachquota}</div>\r\n		\r\n		<div class=\"py-2 border-bottom\"><span class=\"text-muted\">{$lang->usercp[\'attachstats_totaldl\']}</span> {$totaldownloads}</div>\r\n		\r\n			<div class=\"py-2\"><span class=\"text-muted\">{$lang->usercp[\'attachstats_bandwidth\']}</span> {$bandwidth}</div>\r\n		\r\n		</div>\r\n	</div>\r\n</div>\r\n</div>\r\n	</div>\r\n	\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1548','usercp_attachments_attachment','<div class=\"row border-bottom py-2\">\r\n	<div class=\"col-lg-4 align-self-center\">\r\n		{$icon} <a href=\"attachment.php?aid={$attachment[\'aid\']}\" target=\"_blank\">{$attachment[\'filename\']}</a><br /><span class=\"text-muted little\">{$sizedownloads}</span>\r\n	</div>\r\n	<div class=\"col-lg-5 align-self-center\">\r\n		{$lang->usercp[\'attachments_post\']} <a href=\"{$attachment[\'postlink\']}#pid{$attachment[\'pid\']}\">{$attachment[\'subject\']}</a></span>\r\n	</div>\r\n	<div class=\"col-lg-3 align-self-center text-muted text-end\">\r\n		{$attachdate} <input type=\"checkbox\" class=\"form-check-input\" name=\"attachments[{$attachment[\'aid\']}]\" value=\"{$attachment[\'aid\']}\" />\r\n	</div>\r\n\r\n</div>','2','1837','','1720609281');
