INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1594','usercp_notepad','<form action=\"usercp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"card mb-4\">\r\n<div class=\"card-body\">\r\n	<label><strong>{$lang->personal_notepad}</strong></label>\r\n	\r\n\r\n	<textarea name=\"notepad\" id=\"notepad\" cols=\"1\" rows=\"10\" class=\"form-control form-control-sm border\" style=\"height: 200px; resize: none\">{$mybb->user[\'notepad\']}</textarea>\r\n		</div>\r\n	<div class=\"card-footer text-center\">\r\n		<input type=\"hidden\" name=\"action\" value=\"do_notepad\" />\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->update_notepad}\" /><i class=\"fa-solid fa-note-sticky\"></i> &nbsp;{$lang->update_notepad}</button>\r\n</form>\r\n</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1595','usercp_options','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->usercp[\'edit_options\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n<form action=\"usercp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n\r\n{$errors}				\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	\r\n	{$canbeinvisible}\r\n	\r\n	\r\n	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'messaging_notification\']}</div>\r\n	<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'messaging_notification\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n		\r\n		\r\n		<div class=\"form-check\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"commentpm\" id=\"commentpm\" value=\"1\" {$allowcommentpm} />\r\n  <label class=\"form-check-label\" for=\"flexSwitchCheckDefault\">{$lang->usercp[\'pm10\']}</label>\r\n</div>\r\n			\r\n<div class=\"form-check\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"allownotices\" id=\"allownotices\" value=\"1\" {$allownoticescheck} />\r\n  <label class=\"form-check-label\" for=\"flexSwitchCheckDefault\">{$lang->usercp[\'allow_notices\']}</label>\r\n</div>\r\n	<div class=\"form-check\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"hideemail\" id=\"hideemail\" value=\"1\" {$hideemailcheck} />\r\n  <label class=\"form-check-label\" for=\"flexSwitchCheckDefault\">{$lang->usercp[\'allow_emails\']}</label>\r\n</div>\r\n{$pms}\r\n	<div class=\"form-check\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"buddyrequestsauto\" id=\"buddyrequestsauto\" value=\"1\" {$buddyrequestsautocheck} />\r\n  <label class=\"form-check-label\" for=\"flexSwitchCheckDefault\">{$lang->usercp[\'buddyrequests_auto\']}</label>\r\n			</div>\r\n			\r\n		<div class=\"form-group mt-4\">\r\n	<label>{$lang->usercp[\'subscription_method\']}</label>\r\n	<select name=\"subscriptionmethod\" id=\"subscriptionmethod\" class=\"form-select form-select-sm border w-auto pe-5\">\r\n		<option value=\"0\" {$no_auto_subscribe_selected}>{$lang->usercp[\'no_auto_subscribe\']}</option>\r\n		<option value=\"1\" {$no_subscribe_selected}>{$lang->usercp[\'no_subscribe\']}</option>\r\n		<option value=\"2\" {$instant_email_subscribe_selected}>{$lang->usercp[\'instant_email_subscribe\']}</option>\r\n		<option value=\"3\" {$instant_pm_subscribe_selected}>{$lang->usercp[\'instant_pm_subscribe\']}</option>\r\n	</select>\r\n		</div>\r\n			\r\n		</div>\r\n		</div>\r\n		\r\n		<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'date_time_options\']}</div>\r\n	<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'date_time_options\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n			<div class=\"mb-3 pb-4 border-bottom\">\r\n				<label for=\"dateformat\">{$lang->usercp[\'date_format\']}</label>\r\n<select name=\"dateformat\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n<option value=\"0\">{$lang->usercp[\'use_default\']}</option>\r\n{$date_format_options}\r\n</select>\r\n			</div>\r\n			<div class=\"mb-3 pb-4 border-bottom\">\r\n			<label for=\"timeformat\">{$lang->usercp[\'time_format\']}</label>\r\n<select name=\"timeformat\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n<option value=\"0\">{$lang->usercp[\'use_default\']}</option>\r\n{$time_format_options}\r\n</select>\r\n		</div>\r\n			<label>{$lang->usercp[\'time_offset\']}</label>\r\n			{$tzselect}\r\n			\r\n			<div class=\"mb-2 pb-3\">\r\n			<label for=\"dstcorrection\">{$lang->usercp[\'dst_correction\']}</label>\r\n<select name=\"dstcorrection\" class=\"form-select form-select-sm border w-auto pe-5\">\r\n		<option value=\"2\" {$dst_auto_selected}>{$lang->usercp[\'dst_correction_auto\']}</option>\r\n		<option value=\"1\" {$dst_enabled_selected}>{$lang->usercp[\'dst_correction_enabled\']}</option>\r\n		<option value=\"0\" {$dst_disabled_selected}>{$lang->usercp[\'dst_correction_disabled\']}</option>\r\n	</select>\r\n			</div>\r\n			\r\n		</div>\r\n		</div>\r\n	\r\n	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'forum_display_options\']}</div>\r\n	<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'forum_display_options\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n			<div class=\"mb-3 pb-4 border-bottom\">\r\n			<label for=\"daysprune\">{$lang->usercp[\'thread_view\']}</label>\r\n<select name=\"daysprune\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n<option value=\"\">{$lang->usercp[\'use_default\']}</option>\r\n<option value=\"1\" {$daysprunesel[\'1\']}>{$lang->usercp[\'thread_view_lastday\']}</option>\r\n<option value=\"5\" {$daysprunesel[\'5\']}>{$lang->usercp[\'thread_view_5days\']}</option>\r\n<option value=\"10\" {$daysprunesel[\'10\']}>{$lang->usercp[\'thread_view_10days\']}</option>\r\n<option value=\"20\" {$daysprunesel[\'20\']}>{$lang->usercp[\'thread_view_20days\']}</option>\r\n<option value=\"50\" {$daysprunesel[\'50\']}>{$lang->usercp[\'thread_view_50days\']}</option>\r\n<option value=\"75\" {$daysprunesel[\'75\']}>{$lang->usercp[\'thread_view_75days\']}</option>\r\n<option value=\"100\" {$daysprunesel[\'100\']}>{$lang->usercp[\'thread_view_100days\']}</option>\r\n<option value=\"365\" {$daysprunesel[\'365\']}>{$lang->usercp[\'thread_view_year\']}</option>\r\n<option value=\"9999\" {$daysprunesel[\'9999\']}>{$lang->usercp[\'thread_view_all\']}</option>\r\n</select>\r\n			</div>\r\n			\r\n			{$tppselect}\r\n			\r\n		</div>\r\n	</div>\r\n	\r\n\r\n	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'thread_view_options\']}</div>\r\n	<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'thread_view_options\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n			<div class=\"mb-3 pb-4 border-bottom\">\r\n			\r\n	<div class=\"form-check\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"showsigs\" id=\"showsigs\" value=\"1\" {$showsigscheck} />\r\n  <label class=\"form-check-label\" for=\"flexSwitchCheckDefault\">{$lang->usercp[\'show_sigs\']}</label>\r\n</div>\r\n	<div class=\"form-check\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"showavatars\" id=\"showavatars\" value=\"1\" {$showavatarscheck} />\r\n  <label class=\"form-check-label\" for=\"flexSwitchCheckDefault\">{$lang->usercp[\'show_avatars\']}</label>\r\n</div>\r\n\r\n			</div>\r\n			\r\n			\r\n			{$pppselect}\r\n			\r\n			{$pppselect2}\r\n			\r\n		</div>\r\n	</div>\r\n	\r\n		<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'other_options\']}</div>\r\n	<div class=\"row g-3 m-auto pb-0 pt-0 mb-2\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'other_options\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n			<div class=\"mb-3 pb-4 border-bottom\">\r\n		<div class=\"form-check\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"showredirect\" id=\"showredirect\" value=\"1\" {$showredirectcheck} />\r\n  <label class=\"form-check-label\" for=\"flexSwitchCheckDefault\">{$lang->usercp[\'show_redirect\']}</label>\r\n</div>\r\n</div>\r\n		\r\n			\r\n			\r\n		</div>\r\n	</div>\r\n		\r\n	\r\n		</div>\r\n<div class=\"card-footer text-center\">\r\n<input type=\"hidden\" name=\"action\" value=\"do_options\" />\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"regsubmit\" value=\"{$lang->usercp[\'update_options\']}\"><i class=\"fa-solid fa-sliders\"></i> &nbsp;{$lang->usercp[\'update_options\']}</button>\r\n</div>\r\n\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n</form>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
