INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('577','global_bannedwarning','<html>\r\n<head>\r\n  <title>{$title}</title>\r\n  {$headerinclude}\r\n  <link href=\"{$BASEURL}/include/templates/default/style/bootstrap-icons.css\" rel=\"stylesheet\">\r\n  <link href=\"{$BASEURL}/include/templates/default/style/errorss.css\" rel=\"stylesheet\">\r\n\r\n</head>\r\n<body>\r\n  {$header}\r\n\r\n  \r\n \r\n  \r\n    <div class=\"card error-card\">\r\n      <div class=\"card-header22\">\r\n        <i class=\"bi bi-exclamation-triangle-fill error-icon\"></i>\r\n        <div>\r\n          <h2 class=\"mb-0\">Error</h2>\r\n          <p class=\"mb-0 opacity-75\">A problem occurred while processing your request</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"card-body\">\r\n        <div class=\"alert alert-danger\" role=\"alert\">\r\n          <strong>{$lang->global[\'banned_warning\']}</strong>\r\n{$lang->global[\'banned_warning2\']}: {$reason}<br />\r\n{$lang->global[\'banned_warning3\']}: {$banlift}<br />\r\n        </div>\r\n\r\n        \r\n		\r\n		\r\n      </div>\r\n    </div>\r\n\r\n</br>\r\n</body>\r\n</html>','2','1837','','1728810794');
