INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('597','postbit_ignored','<div class=\"ignored_post collapse show\" id=\"ignored_post_{$post[\'pid\']}\">\r\n    <div class=\"ignored_post_author\">\r\n        <strong><span class=\"largetext\">{$post[\'profilelink\']}</span></strong>\r\n    </div>\r\n\r\n    <div class=\"ignored_post_message\">\r\n        <div class=\"show_ignored_post float_right\" style=\"vertical-align: top;\" id=\"show_ignored_link_{$post[\'pid\']}\">\r\n            <button type=\"button\" class=\"btn btn-outline-primary btn-sm rounded-2 d-flex align-items-center gap-2\"\r\n                onclick=\"showIgnoredPost({$post[\'pid\']}); return false;\">\r\n                <i class=\"bi bi-eye\"></i>\r\n                <span>{$lang->global[\'postbit_show_ignored_post\']}</span>\r\n            </button>\r\n        </div>\r\n\r\n        {$ignored_message}\r\n    </div>\r\n</div>\r\n\r\n<script>\r\n// Плавное скрытие/показ через CSS height animation\r\nfunction slideToggle(element, show) {\r\n    if (show) {\r\n        element.style.display = \"block\";\r\n        let height = element.scrollHeight + \"px\";\r\n        element.style.height = \"0px\";\r\n\r\n        requestAnimationFrame(() => {\r\n            element.style.transition = \"height 0.3s ease\";\r\n            element.style.height = height;\r\n        });\r\n\r\n        setTimeout(() => {\r\n            element.style.height = \"\";\r\n            element.style.transition = \"\";\r\n        }, 300);\r\n    } else {\r\n        element.style.height = element.scrollHeight + \"px\";\r\n\r\n        requestAnimationFrame(() => {\r\n            element.style.transition = \"height 0.3s ease\";\r\n            element.style.height = \"0px\";\r\n        });\r\n\r\n        setTimeout(() => {\r\n            element.style.display = \"none\";\r\n            element.style.height = \"\";\r\n            element.style.transition = \"\";\r\n        }, 300);\r\n    }\r\n}\r\n\r\nfunction showIgnoredPost(pid) {\r\n    const ignoredPost = document.getElementById(\"ignored_post_\" + pid);\r\n    const normalPost  = document.getElementById(\"post_\" + pid);\r\n    const button      = document.querySelector(\"#show_ignored_link_\" + pid + \" button\");\r\n    const icon        = button.querySelector(\"i\");\r\n    const text        = button.querySelector(\"span\");\r\n\r\n    const ignoredVisible = ignoredPost.style.display !== \"none\";\r\n\r\n    if (ignoredVisible) {\r\n        // скрываем игнорируемый, показываем обычный\r\n        slideToggle(ignoredPost, false);\r\n        slideToggle(normalPost, true);\r\n\r\n        icon.classList.remove(\"bi-eye\");\r\n        icon.classList.add(\"bi-eye-slash\");\r\n        text.textContent = \"{$lang->global[\'postbit_hide_ignored_post\']}\";\r\n        button.classList.remove(\"btn-outline-primary\");\r\n        button.classList.add(\"btn-outline-secondary\");\r\n    } else {\r\n        // показываем игнорируемый, скрываем обычный\r\n        slideToggle(ignoredPost, true);\r\n        slideToggle(normalPost, false);\r\n\r\n        icon.classList.remove(\"bi-eye-slash\");\r\n        icon.classList.add(\"bi-eye\");\r\n        text.textContent = \"{$lang->global[\'postbit_show_ignored_post\']}\";\r\n        button.classList.remove(\"btn-outline-secondary\");\r\n        button.classList.add(\"btn-outline-primary\");\r\n    }\r\n\r\n    return false;\r\n}\r\n</script>\r\n','2','1809','','1728810794');
